  [9000] = { "Il meglio per ultimo", "Consegna a Deliana la ⟦Beaststalker's Cap=Maschera del Predatore di Bestie⟧ e la ⟦Beaststalker's Tunic=Giubba del Predatore di Bestie⟧.", "Che storia incredibile, {name}! Hai la mia gratitudine, e quella sincera di tutti coloro che vi erano coinvolti. Forse ora riuscirò a dormire la notte con tutti e due gli occhi chiusi.\n\nQuanto alla tua ricompensa, credo di avere qualcosa che ti piacerà davvero.", "Come da accordi, sei pront<o/a> a consegnare i tuoi pezzi del Predatore di Bestie in cambio del nuovo ⟦Beastmaster's Cap=Berretto del Maestro delle Bestie⟧ e della nuova Giubba del Maestro delle Bestie?", "Mi mancherai, {name}. Ho con te un tale debito di gratitudine che credo non riuscirò mai a ripagarlo.\n\nSpero che la tua nuova armatura per testa e torso ti piaccia, e che ti protegga a lungo.", 0x48402900, 0x2be5774f, 0x03db6ed6, 0x043c7993, 0x2cf1dd7a, "....." },
