  [9007] = { "Il meglio per ultimo", "Consegna a Mokvar il ⟦Wildheart Cowl=Copricapo del Cuorselvaggio⟧ e la ⟦Wildheart Vest=Veste del Cuorselvaggio⟧.", "Una storia davvero incredibile, {name}! Hai la mia gratitudine e quella sincera di tutti coloro che vi erano coinvolti, te lo assicuro. Grazie ai tuoi sforzi siamo liberati dagli errori del nostro passato.\n\nQuanto alla tua ricompensa, credo di avere qualcosa che ti sei senz'altro guadagnato e che apprezzerai davvero.", "Come da accordi, sei pront<o/a> a consegnare i tuoi pezzi del Cuorselvaggio in cambio del nuovo ⟦Feralheart Cowl=Copricapo del Cuore Ferino⟧ e della nuova Veste del Cuore Ferino?", "Mi mancherai davvero, {name}. Ho con te un debito che forse non potrò mai saldare.\n\nGoditi la tua nuova armatura per testa e torso. Che ti protegga a lungo e ti aiuti a conquistare un onore ancora più grande!", 0x48402900, 0xa5f70ad7, 0xf3ed443f, 0x7a344d64, 0xe7bcdb0b, "....." },
