  [9014] = { "Il meglio per ultimo", "Consegna a Mokvar la ⟦Magister's Crown=Corona del Magistro⟧ e le ⟦Magister's Robes=Vesti del Magistro⟧.", "Una storia davvero incredibile, {name}! Hai la mia gratitudine e quella sincera di tutti coloro che vi erano coinvolti, te lo assicuro. Grazie ai tuoi sforzi siamo liberati dagli errori del nostro passato.\n\nQuanto alla tua ricompensa, credo di avere qualcosa che ti sei senz'altro guadagnato e che apprezzerai davvero.", "Come da accordi, sei pront<o/a> a consegnare i tuoi pezzi del Magistro in cambio della nuova ⟦Sorcerer's Crown=Corona dell'Occultista⟧ e delle nuove Vesti dell'Occultista?", "Mi mancherai davvero, {name}. Ho con te un debito che forse non potrò mai saldare.\n\nGoditi la tua nuova armatura per testa e torso. Che ti protegga a lungo e ti aiuti a conquistare un onore ancora più grande!", 0x48402900, 0x7709da32, 0xf3ed443f, 0xe56a41b3, 0xe7bcdb0b, "....." },
  [9015] = { "La sfida", "Raggiungi il Ring of the Law nei ⟦Blackrock Depths=Sotterranei di Roccianera⟧ e pianta lo ⟦Banner of Provocation=Stendardo della Provocazione⟧ al centro mentre l'alto giudice Grimstone pronuncia la tua condanna. Uccidi Theldren e i suoi gladiatori e torna da Anthion Harmon, nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧, con il primo frammento dell'Amuleto di Sire Valthalak.", "Ascoltami bene, {name}. Perché lo stendardo funzioni come desideriamo, dovrai entrare nel Ring of the Law, nei ⟦Blackrock Depths=Sotterranei di Roccianera⟧. Lasciati condannare dall'alto giudice Grimstone e pianta con decisione lo stendardo a terra in segno di sfida.\n\nLa tua vittima non riuscirà a trattenersi e scenderà nella mischia, smaniosa di combattere contro di te. Una volta ottenuto ciò che cerchi, torna da Anthion.", "Sei tornat<o/a>, {name}!", "Hai recuperato una parte del medaglione, {name}?", 0xc6735ff8, 0xb45640a2, 0x506b86a7, 0xa0760cc3, 0x144fdc51, "....." },
  [9016] = { "Le ultime parole di Anthion", "Torna da Mokvar a Orgrimmar con un set composto da ⟦Wildheart Boots=Stivali del Cuorselvaggio⟧, ⟦Wildheart Kilt=Kilt del Cuorselvaggio⟧ e ⟦Wildheart Spaulders=Guardaspalle del Cuorselvaggio⟧.", "L'anima di Valthalak era racchiusa in questo amuleto. Accecati dall'avidità, lo dividemmo stoltamente in tre parti, senza sapere quale maledizione ci attendeva.\n\nL'unico modo per fermare l'incantesimo di Valthalak è rimettere insieme l'amuleto. Torna da Mokvar e digli che Bodley è la sua unica speranza di trovare i frammenti mancanti. Parla con lui delle ricompense che avete pattuito.\n\nIo, finalmente, riposerò in pace. Ti auguro tutta la fortuna possibile: ne avrai bisogno fino all'ultima goccia!", "Sei tornat<o/a> e vedo nei tuoi occhi che hai molto da raccontarmi, {name}. Pensiamo prima alla tua ricompensa.", "Questa maledizione ci è stata scagliata addosso per un semplice medaglione. Lord Valthalak sa davvero come serbare rancore.\n\nCi sforzeremo di trovare i pezzi mancanti, sperando di farcela prima di fare una fine prematura. Ma prima pensiamo alla tua ricompensa.", 0x4e493fc8, 0x03ea45cc, 0xbf3e43cf, 0x9753571f, 0x065d55b0, "....." },
