  [9019] = { "Le ultime parole di Anthion", "Torna da Mokvar a Orgrimmar con un set composto da ⟦Devout Sandals=Grancalzari del Devoto⟧, ⟦Devout Skirt=Gonna del Devoto⟧ e ⟦Devout Mantle=Coprispalle del Devoto⟧.", "L'anima di Valthalak era racchiusa in questo amuleto. Accecati dall'avidità, lo dividemmo stoltamente in tre parti, senza sapere quale maledizione ci attendeva.\n\nL'unico modo per fermare l'incantesimo di Valthalak è rimettere insieme l'amuleto. Torna da Mokvar e digli che Bodley è la sua unica speranza di trovare i frammenti mancanti. Parla con lui delle ricompense che avete pattuito.\n\nIo, finalmente, riposerò in pace. Ti auguro tutta la fortuna possibile: ne avrai bisogno fino all'ultima goccia!", "Sei tornat<o/a> e vedo nei tuoi occhi che hai molto da raccontarmi, {name}. Pensiamo prima alla tua ricompensa.", "Questa maledizione ci è stata scagliata addosso per un semplice medaglione. Lord Valthalak sa davvero come serbare rancore.\n\nCi sforzeremo di trovare i pezzi mancanti, sperando di farcela prima di fare una fine prematura. Ma prima pensiamo alla tua ricompensa.", 0x4e493fc8, 0xceb83d1b, 0xbf3e43cf, 0x9753571f, 0x065d55b0, "....." },
  [9020] = { "Le ultime parole di Anthion", "Torna da Mokvar a Orgrimmar con un set composto da ⟦Shadowcraft Boots=Stivali del Creatore d'Ombra⟧, ⟦Shadowcraft Pants=Pantaloni del Creatore d'Ombra⟧ e ⟦Shadowcraft Spaulders=Guardaspalle del Creatore d'Ombra⟧.", "L'anima di Valthalak era racchiusa in questo amuleto. Accecati dall'avidità, lo dividemmo stoltamente in tre parti, senza sapere quale maledizione ci attendeva.\n\nL'unico modo per fermare l'incantesimo di Valthalak è rimettere insieme l'amuleto. Torna da Mokvar e digli che Bodley è la sua unica speranza di trovare i frammenti mancanti. Parla con lui delle ricompense che avete pattuito.\n\nIo, finalmente, riposerò in pace. Ti auguro tutta la fortuna possibile: ne avrai bisogno fino all'ultima goccia!", "Sei tornat<o/a> e vedo nei tuoi occhi che hai molto da raccontarmi, {name}. Pensiamo prima alla tua ricompensa.", "Questa maledizione ci è stata scagliata addosso per un semplice medaglione. Lord Valthalak sa davvero come serbare rancore.\n\nCi sforzeremo di trovare i pezzi mancanti, sperando di farcela prima di fare una fine prematura. Ma prima pensiamo alla tua ricompensa.", 0x4e493fc8, 0xcecbaf6e, 0xbf3e43cf, 0x9753571f, 0x065d55b0, "....." },
  [9021] = { "Le ultime parole di Anthion", "Torna da Mokvar a Orgrimmar con un set composto da ⟦Dreadmist Sandals=Grancalzari Brumafunesta⟧, ⟦Dreadmist Leggings=Gambiere Brumafunesta⟧ e ⟦Dreadmist Mantle=Coprispalle Brumafunesta⟧.", "L'anima di Valthalak era racchiusa in questo amuleto. Accecati dall'avidità, lo dividemmo stoltamente in tre parti, senza sapere quale maledizione ci attendeva.\n\nL'unico modo per fermare l'incantesimo di Valthalak è rimettere insieme l'amuleto. Torna da Mokvar e digli che Bodley è la sua unica speranza di trovare i frammenti mancanti. Parla con lui delle ricompense che avete pattuito.\n\nIo, finalmente, riposerò in pace. Ti auguro tutta la fortuna possibile: ne avrai bisogno fino all'ultima goccia!", "Sei tornat<o/a> e vedo nei tuoi occhi che hai molto da raccontarmi, {name}. Pensiamo prima alla tua ricompensa.", "Questa maledizione ci è stata scagliata addosso per un semplice medaglione. Lord Valthalak sa davvero come serbare rancore.\n\nCi sforzeremo di trovare i pezzi mancanti, sperando di farcela prima di fare una fine prematura. Ma prima pensiamo alla tua ricompensa.", 0x4e493fc8, 0xd3297fbe, 0xbf3e43cf, 0x9753571f, 0x065d55b0, "....." },
  [9022] = { "Le ultime parole di Anthion", "Torna da Mokvar a Orgrimmar con un set composto da ⟦Boots of Valor=Stivali del Valore⟧, ⟦Legplates of Valor=Gambali Corazzati del Valore⟧ e ⟦Spaulders of Valor=Guardaspalle del Valore⟧.", "L'anima di Valthalak era racchiusa in questo amuleto. Accecati dall'avidità, lo dividemmo stoltamente in tre parti, senza sapere quale maledizione ci attendeva.\n\nL'unico modo per fermare l'incantesimo di Valthalak è rimettere insieme l'amuleto. Torna da Mokvar e digli che Bodley è la sua unica speranza di trovare i frammenti mancanti. Parla con lui delle ricompense che avete pattuito.\n\nIo, finalmente, riposerò in pace. Ti auguro tutta la fortuna possibile: ne avrai bisogno fino all'ultima goccia!", "Sei tornat<o/a> e vedo nei tuoi occhi che hai molto da raccontarmi, {name}. Pensiamo prima alla tua ricompensa.", "Questa maledizione ci è stata scagliata addosso per un semplice medaglione. Lord Valthalak sa davvero come serbare rancore.\n\nCi sforzeremo di trovare i pezzi mancanti, sperando di farcela prima di fare una fine prematura. Ma prima pensiamo alla tua ricompensa.", 0x4e493fc8, 0xf397e78b, 0xbf3e43cf, 0x9753571f, 0x065d55b0, "....." },
  [9023] = { "Il veleno perfetto", "Dirk Thunderwood, alla ⟦Cenarion Hold=Fortezza Cenariana⟧, vuole che tu gli porti Venoxis's Venom Sac e ⟦Kurinnaxx's Venom Sac=Sacca di Veleno di Kurinnaxx⟧.", "Io e mio fratello gestiamo le operazioni dei veleni dal Maniero dei ⟦Ravenholdt=Corvolesto⟧.\n\nLord Ravenholdt mi ha incaricato di trovare un nuovo composto velenoso, estremamente efficace, che si può ricavare dalle sacche di veleno degli abitanti di ⟦Zul'Gurub=Zul'gurub⟧ e delle ⟦Ruins of Ahn'Qiraj=Rovine di Ahn'qiraj⟧.\n\nIn quelle maledette rovine vivono due bestie particolarmente velenose che possiedono ciò che potremmo cercare, {class}. Portami una sacca di veleno delle bestie Kurinnaxx e Venoxis e te ne saremo eternamente grati.", "Non è un lavoretto da mordi e fuggi, {name}. Dovrai portarti degli amici.", "⟦Ravenholdt=Corvolesto⟧ ti ringrazia, eroe! Scegli pure!", 0xa122e31b, 0xccf6f935, 0x7be5d33f, 0xda1def79, 0xf94a859c, "....." },
  [9024] = { "Il sospetto di Aristan", "Porta 1 ⟦Cologne Bottle=Boccetta di Colonia⟧ e 1 ⟦Perfume Bottle=Boccetta di Profumo⟧ a Morgan Pestle, nel ⟦Trade District=Quartiere del Commercio⟧ di ⟦Stormwind=Roccavento⟧.", "Ci sono! Hai sentito la nuova fragranza nell'aria? Le nuove colonie e i nuovi profumi che sono diventati di moda? Le nostre guardie non trascurerebbero i loro doveri così facilmente.\n\nA meno che i loro pensieri non siano stati annebbiati da qualche losca alchimia.\n\nC'è un solo modo per esserne sicuri: porta una boccetta di colonia e una di profumo a Morgan Pestle e riferiscigli i miei sospetti. Quando tornerai ti rimborserò l'acquisto.", "Posso aiutarti in qualcosa?", "Capisco le preoccupazioni di Aristan, ma credo proprio che stia esagerando. Lascia che i giovani facciano quel che vogliono. Credo che Aristan abbia dimenticato cosa significa essere giovani e innamorati.\n\nMa sarebbe meglio non dirglielo. Assecondiamolo.", 0xbf4e5c34, 0x40cb68d0, 0x707e9534, 0xdf112bb5, 0x261a5993, "....." },
  [9025] = { "La scoperta di Morgan", "Torna da Aristan Mottar, fuori dalla banca nel ⟦Trade District=Quartiere del Commercio⟧ di Roccavento.", "Ma guarda un po'. Sembra che Aristan abbia visto giusto, dopotutto. Ho trovato tracce di sostanze usate nei filtri d'amore e in subdole pozioni che alterano la mente.\n\nNon è insolito che i profumi ne contengano un po', ma alcuni degli ingredienti che ho rilevato... C'è qualcosa che puzza.", nil, "Anche se pensavo che sarebbe andata così, scoprire che i miei sospetti erano fondati è comunque inquietante. Dobbiamo valutare con attenzione la nostra prossima mossa.\n\nEcco, per rimborsarti l'acquisto della colonia e del profumo.", 0x00276958, 0x74854d2a, 0x275c2471, nil, 0xa0c5854e, "...m." },
  [9026] = { "Sulle tracce della fonte", "Parla con la locandiera Allison al Gilded Rose, nel ⟦Trade District=Quartiere del Commercio⟧ di Roccavento.", "Dobbiamo trovare la fonte. Ho visto molta più gente del solito, guardie comprese, entrare e uscire dal Gilded Rose. Parla con Allison. Se è lei a venderli, potrà dirti da dove arrivano.", nil, "Oh sì, il profumo e la colonia mi sono arrivati da poco. Si vendono così bene che non so per quanto riuscirò a tenerli sugli scaffali.\n\nSe vuoi sapere come la penso, è un po' noioso. Tutti con lo stesso odore? Profuma benissimo, ma comunque.", 0xc4ef4d74, 0x9259fd91, 0xf8ad7b44, nil, 0x15074611, "...m." },
  [9027] = { "Sulle tracce della fonte", "Parla con Evert Sorisam nel negozio The Finest Thread, lungo i canali di Roccavento.", "Qualcosa di strano nella colonia? Può darsi. Non ho mai visto tanta gente andare dietro a un prodotto come questo.\n\nSenti, se c'è qualcosa che non va, voglio saperlo anch'io. Ho comprato la mia scorta da un mercante di nome Evert Sorisam. È nuovo in città.\n\nHa detto che aveva della merce da consegnare a The Finest Thread.", nil, "Sì, certo. Quelle fragranze sono gli articoli più richiesti della stagione. Sarai la quinta o sesta persona che me ne chiede in quest'ora.\n\nPurtroppo le mie scorte sono esaurite. Se ne vuoi un po', dovresti parlare con Allison, la locandiera del Gilded Rose.\n\nPerò non perdere tempo. Credo che troverai <la/il> <colonia/profumo> irresistibile.", 0xc4ef4d74, 0xec408413, 0xd233b69d, nil, 0x0f5247b3, "...m.", nil, nil, nil, nil, 0xb83ac954 },
  [9028] = { "La fonte svelata", "Trova lo speziale Staffron Lerent nelle ⟦Hillsbrad Foothills=Alture di Colletorto⟧, dietro il ⟦Ravenholdt Manor=Maniero dei Corvolesto⟧.", "Cosa? Tradimento? No, no. Ti assicuro che le mie intenzioni sono del tutto innocue.\n\nÈ così sbagliato aiutare chi desidera alleviare il doloroso rituale del corteggiamento? Suvvia, non è un crimine.\n\nE per dimostrarti che non voglio fare del male, ti dirò perfino chi è il mio fornitore.\n\nMe li ha spediti un certo Staffron Lerent, una specie di speziale. Non ci ho mai parlato.\n\nIl nostro intermediario goblin ha detto che lavorava sulle alture sopra ⟦Hillsbrad=Colletorto⟧, oltre quel misterioso ⟦Ravenholdt Manor=Maniero dei Corvolesto⟧. Ti auguro buona fortuna nel trovarlo.", nil, "Sì, ho creato io quelle fragranze. Un profumo meraviglioso, vero? Irresistibile.\n\nUna volta che i guerrieri dell'⟦Alliance=Alleanza⟧ e dell'⟦Horde=Orda⟧ saranno travolti da questi sentimenti d'amore, non avranno la forza di fermare l'ascesa del ⟦Shadow Council=Concilio dell'Ombra⟧.\n\nSaranno indeboliti, impreparati. Preoccupati per i loro cari, perderanno il loro vantaggio.\n\nLa soluzione era così semplice. Perché mi ci è voluto tanto per arrivarci? Il punto debole di tutti è il cuore. E non c'è nulla che tu possa fare per fermare l'inevitabile.", 0xf2e77961, 0x9b987c7a, 0x9dec14e0, nil, 0x904005d0, "...m." },
  [9029] = { "Un calderone ribollente", nil, nil, nil, "Dal calderone sale un odore gradevole.", 0xadb71af2, nil, nil, nil, 0x175eed11, ".mmm." },
  [9030] = { "Le ultime parole di Anthion", "Parla con Deliana a ⟦Ironforge=Forgiardente⟧.", "L'anima di Valthalak era racchiusa in questo amuleto. Nella nostra avidità lo abbiamo stoltamente diviso in tre parti, senza sapere quale maledizione ci attendesse.\n\nL'unico modo per fermare l'incantesimo di Valthalak è ricomporre il medaglione. Torna da Deliana e dille che Bodley è la sua unica speranza di trovare i pezzi mancanti.\n\nIo, per una volta, riposerò in pace. Ti auguro tutta la fortuna possibile, e ne avrai bisogno!", nil, nil, 0x4e493fc8, 0xa520f889, 0xfc39c874, nil, nil, "...mm" },
  [9032] = { "La triste sorte di Bodley", "Raggiungi il ⟦Blackrock Mountain=Massiccio Roccianera⟧ e usa il ⟦Extra-Dimensional Ghost Revealer=Rivelatore di Fantasmi Extradimensionale⟧ per trovare Bodley vicino ai ⟦Blackrock Spire=Bastioni di Roccianera⟧.", "Il medaglione conteneva l'anima di Valthalak? Non c'è da stupirsi che fosse protetto da una maledizione così potente.\n\nTrovare Bodley è un bel problema. L'ultima volta che ne ho sentito parlare, si preparava a tornare ai ⟦Blackrock Spire=Bastioni di Roccianera⟧. Da allora non se n'è saputo più nulla.\n\nCercalo nel ⟦Blackrock Mountain=Massiccio Roccianera⟧, anche se temo che ormai sia morto. Ti consiglio di portare con te il congegno del goblin, amico.", nil, "Sono così felice che tu riesca a vedermi. Finalmente qualcuno con cui parlare!\n\nCi aiuterai, {name}? Ci aiuterai a riparare il torto che abbiamo commesso e a rimettere le cose a posto? Se è vero che hai già il Frammento Superiore dell'Amuleto di Sire Valthalak, credo di poterti indicare la strada giusta per ottenere le altre due parti, riunirle e mettere fine a tutto questo.\n\nOh, a proposito, ciao, mi chiamo Bodley. Piacere di conoscerti!", 0x87a6a36a, 0x180c9e9b, 0x5728da71, nil, 0x077dc9c4, "...m." },
  [9033] = { "Echi di guerra", "Il comandante Eligor Dawnbringer, alla ⟦Light's Hope Chapel=Cappella della Luce⟧ nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧, vuole che tu uccida 5 Living Monstrosity, 5 Stoneskin Gargoyle, 8 Deathknight Captain e 3 Venom Stalker.", "Cinque anni dall'ultima guerra...\n\nDecine di migliaia di vite perdute, e per cosa? La minaccia non è mai stata del tutto estinta.\n\nE così il Re dei Lich si risveglia ancora una volta... Il suo tirapiedi, Kel'Thuzad, ammassa le forze per un nuovo attacco alle nostre terre.\n\nNon lo permetteremo! Dimostra la tua dedizione. Dimostra di essere dispost<o/a> a rischiare la vita per fermare questa follia, e la forza congiunta dell'Alba e della Crociata sarà ai tuoi ordini.\n\nEntra a Naxxramas e distruggi il Flagello che vi si annida...", "Dovere, onore, dedizione... Cosa significano per te queste parole?", "Ottimo lavoro! Sarai ricompensat<o/a> grazie ai servigi degli uomini e delle donne della Cappella della Luce.", 0xc78c127b, 0xfa049933, 0x3ae1b39e, 0x7615fd9e, 0x06516fca, "....." },
  [9051] = { "Prova tossica", "Pugnala un Devilsaur con la ⟦Devilsaur Barb=Daga del Gigantosauro⟧. Quando avrai completato questo compito, torna da Torwa Pathfinder nel ⟦Un'Goro Crater=Cratere di Un'Goro⟧.", "La tossina che mi hai aiutato a creare ha uno scopo speciale. I grandi gigantosauri del cratere rendono pericoloso cacciare e difficile sopravvivere per me. Anche se avessi la forza necessaria, uccidere un gigantosauro permetterebbe semplicemente a un altro di prendersi il suo territorio.\n\nPrendi questa daga avvelenata e piantala a fondo in un gigantosauro vivo. La tossina dovrebbe calmare la creatura, anche se non so quanto in fretta...", "Sei riuscit<o/a> a calmare la grande bestia?", "Grazie, {name}. Sei <coraggioso/coraggiosa> e <saggio/saggia>.\n\nDimmi, come ha reagito il gigantosauro alla tossina?", 0x48054159, 0x6be611fa, 0x8ef8e482, 0x1e668d2c, 0x521708f1, "....." },
  [9052] = { "⟦Bloodpetal Poison=Veleno di Petalorosso⟧", "Raccogli 8 Bloodcap e 8 Aculeo dei Gorishi, poi torna da Torwa Pathfinder nel ⟦Un'Goro Crater=Cratere di Un'Goro⟧.", "Vorrei chiederti di aiutarmi a creare una specie di tossina, per calmare una grande creatura che vive qui nel cratere. Non è letale, e solo gli occhi acuti di <un/una> {class} possono sperare di raccoglierne gli ingredienti.\n\nTroverai i funghi Bloodcap che crescono dentro i germogli di petalorosso in tutto il cratere. Gli aculei dei Gorishi vengono dalle vespe giganti volanti dentro e intorno all'Anfratto Brulicante, nella parte meridionale del cratere.", "Hai avuto successo?", "Finalmente gli ingredienti!\n\nCon il terreno di Un'Goro che ho raccolto, la tossina si prepara facilmente...", 0x1f178293, 0xf06ff794, 0xd296bd83, 0x7cadef78, 0x01ac2d01, "....." },
  [9053] = { "Un ingrediente migliore", "Recupera una ⟦Putrid Vine=Vite Putrida⟧ dal guardiano in fondo al Tempio di Atal'Hakkar e torna da Torwa Pathfinder.", "È come temevo: la tossina è semplicemente troppo debole per una creatura così potente.\n\nSe vogliamo creare una tossina abbastanza potente, devi scendere fino in fondo al Tempio di Atal'Hakkar, svelare i segreti dell'altare e recuperare una vite putrida dal guardiano che vi si trova. Il tempio è pericoloso, e faresti bene a portare degli amici.\n\nTorna da me quando avrai finito.", "Hai recuperato la vite?", "Finalmente la tossina può essere creata per intero. Non oso chiederti di infliggerla di nuovo alla creatura: ti ho già chiesto troppo.\n\nHai la mia gratitudine e il mio rispetto. Che i tuoi viaggi ti siano propizi, {name}.", 0xdb190fa9, 0x0ad68432, 0x3f4b427f, 0x25aa9248, 0xa8224e50, "....." },
  [9063] = { nil, "Parla con Torwa Pathfinder nel ⟦Un'Goro Crater=Cratere di Un'Goro⟧.", "Un cacciatore di nome Torwa Pathfinder ha chiesto l'aiuto di un druido. Ha detto che solo noi possediamo le capacità e il rispetto per la natura necessari per aiutarlo.\n\nC'è una strada che collega il ⟦Un'Goro Crater=Cratere di Un'Goro⟧ al deserto di Tanaris. Dove quella strada entra nel cratere, troverai Torwa lì vicino.", nil, "Hai viaggiato a lungo per incontrarmi, {class}, e appena in tempo.", 0x168fa4b2, 0x21114ed8, 0x5987fa9c, nil, 0x75c76210, "e..m." },
  [9065] = { "La missione \"Chow\" (123)aa", "Uccidi ⟦Kobold Vermin=Coboldo Parassita⟧, 2 in tutto.", "$N1! Uccidi ⟦Kobold Vermin=Coboldo Parassita⟧, 2 in tutto.", nil, nil, 0xdb0905c3, 0x314b469d, 0xb19a2ce2, nil, nil, "...mm" },
  [9085] = { "Ombre di sventura", "Raggiungi un cerchio d'evocazione e uccidi uno Shadow of Doom, poi torna dal comandante Thomas Helleran alla ⟦Light's Hope Chapel=Cappella della Luce⟧, nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧.", "Dopo aver abbattuto le difese dei cerchi d'evocazione del Flagello comparsi nelle zone sotto attacco, potrai affrontare gli accoliti che li proteggono.\n\nIn verità non sono uomini. Sono ombre, tra le creature più terrificanti del Re dei Lich. Si possono smascherare con le rune necrotiche che portano con sé, e poi distruggere con la magia o con la forza delle armi.", "Hai avuto fortuna, {name}?", "Ottimo lavoro, {name}. Con le ombre distrutte, è solo questione di tempo prima che il Re dei Lich decida di richiamare le sue necropoli e lasciarci in pace.", 0xb93e11b0, 0xa5c9c54e, 0x3d7faa8c, 0x10763147, 0x6b4b125c, "....." },
  [9120] = { "La caduta di Kel'Thuzad", "Porta il Filatterio di Kel'Thuzad alla ⟦Light's Hope Chapel=Cappella della Luce⟧, nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧.", "Il filatterio è tutto ciò che resta del signore di Naxxramas. Il buon senso ti suggerisce di distruggerlo, per impedire al lich di riformarsi. Per fortuna, dai di rado ascolto a quella voce interiore della ragione.\n\nQualcuno alla Cappella della Luce ti pagherà profumatamente per questo manufatto. Che importa se Kel'Thuzad torna alla sua piena potenza?", nil, nil, 0x480d1191, 0x4c963af8, 0x2c6511e8, nil, nil, "...mm" },
  [9121] = { "La temibile cittadella - Naxxramas", "L'arcimaga Angela Dosantos alla ⟦Light's Hope Chapel=Cappella della Luce⟧, nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧, vuole 5 Cristallo Arcano, 2 Nexus Crystal, 1 ⟦Righteous Orb=Globo Virtuoso⟧ e 60 monete d'oro. Devi anche essere Onorato presso l'⟦Argent Dawn=Alba d'Argento⟧.", "Nel cuore di ⟦Plaguewood=Malaselva⟧ si trova l'ingresso della temibile cittadella di Naxxramas. Finora ogni tentativo di entrare era stato sventato dagli incantesimi di protezione posti sul portale runico. Fino a ora, almeno.\n\nAbbiamo escogitato un modo per entrare grazie a una copertura arcana: un vecchio incantesimo minore del Kirin Tor, con qualche modifica di mia invenzione. Dato che la tua dedizione alla causa dell'Alba lascia un po' a desiderare, {name}, il prezzo sarà alto. Puoi rinunciare e tornare quando avrai una reputazione Riverito o Osannato, per avere uno sconto.", "Nessuno è entrato a Naxxramas ed è sopravvissuto per raccontarlo.", "Sentirai un leggero formicolio, {name}. Vuol dire che funziona. Una volta finito, potrai entrare a Naxxramas salendo sul portale runico a ⟦Plaguewood=Malaselva⟧.", 0x289d201e, 0x5bb64924, 0xea550201, 0x9ab9bbde, 0xa4fd1bd1, "....." },
  [9122] = { "La temibile cittadella - Naxxramas", "L'arcimaga Angela Dosantos alla ⟦Light's Hope Chapel=Cappella della Luce⟧, nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧, vuole 2 Cristallo Arcano, 1 Nexus Crystal e 30 monete d'oro. Devi anche essere Riverito presso l'⟦Argent Dawn=Alba d'Argento⟧.", "Nel cuore di ⟦Plaguewood=Malaselva⟧ si trova l'ingresso della temibile cittadella di Naxxramas. Finora ogni tentativo di entrare era stato sventato dagli incantesimi di protezione posti sul portale runico. Fino a ora, almeno.\n\nAbbiamo escogitato un modo per entrare grazie a una sorta di copertura arcana permanente: un vecchio incantesimo minore del Kirin Tor, con qualche modifica di mia invenzione. Detto questo, la copertura è costosa. Dato che la tua dedizione alla causa dell'Alba è ammirevole, siamo disposti a sostenere parte dei costi.", "Nessuno è entrato a Naxxramas ed è sopravvissuto per raccontarlo.", "Sentirai un leggero formicolio, {name}. Vuol dire che funziona. Una volta finito, potrai entrare a Naxxramas salendo sul portale runico a ⟦Plaguewood=Malaselva⟧.", 0x289d201e, 0x9f229efd, 0x3d6fd285, 0x9ab9bbde, 0xa4fd1bd1, "....." },
  [9123] = { "La temibile cittadella - Naxxramas", "L'arcimaga Angela Dosantos alla ⟦Light's Hope Chapel=Cappella della Luce⟧, nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧, ti concederà la ⟦Arcane Cloaking=Copertura Arcana⟧ senza alcun costo. Devi essere Osannato presso l'⟦Argent Dawn=Alba d'Argento⟧.", "Nel cuore di ⟦Plaguewood=Malaselva⟧ si trova l'ingresso della temibile cittadella di Naxxramas. Finora ogni tentativo di entrare era stato sventato dagli incantesimi di protezione posti sul portale runico. Fino a ora, almeno.\n\nAbbiamo escogitato un modo per entrare grazie a una sorta di copertura arcana permanente: un vecchio incantesimo minore del Kirin Tor, con qualche modifica di mia invenzione. Detto questo, la copertura è costosa; tuttavia, la tua dedizione alla causa dell'Alba è incrollabile! Rinunceremo a qualsiasi pagamento.", "Nessuno è entrato a Naxxramas ed è sopravvissuto per raccontarlo.", "Sentirai un leggero formicolio, {name}. Vuol dire che funziona. Una volta finito, potrai entrare a Naxxramas salendo sul portale runico a ⟦Plaguewood=Malaselva⟧.", 0x289d201e, 0x69b682cf, 0x92dc890b, 0x9ab9bbde, 0xa4fd1bd1, "....." },
  [9124] = { "L'armatura Cryptstalker non si fa da sola...", "Il cacciatore Leopold, alla ⟦Light's Hope Chapel=Cappella della Luce⟧ nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧, vuole 30 ⟦Crypt Fiend Parts=Parti di Ragno delle Cripte⟧.", "Che ne diresti di guadagnarti una di queste monete luccicanti?\n\n<Leopold solleva un'insegna della Crociata.>\n\nHo un piccolo problema in cui potresti aiutarmi, {name}. Vedi, io realizzo armature Cryptstalker per chi è abbastanza matto da avventurarsi a Naxxramas. Loro mi forniscono i materiali principali per l'armatura, ma io resto sempre senza parti di ragno delle cripte. Portami un fascio di parti e ti pagherò con un'insegna, utilizzabile presso il quartiermastro.", "Come va la caccia?", "Ah, questo andrà benissimo, {name}. Ricorda, accetto sempre altre parti. Per ogni fascio che mi porti, ti ricompenserò con un'insegna.", 0xa2b385ba, 0x878a3fbf, 0x61c659aa, 0xe02b27bb, 0xe90182ae, "....." },
  [9126] = { "Scavi per la Falce Ossuta", "Rohan l'Assassino alla ⟦Light's Hope Chapel=Cappella della Luce⟧, nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧, vuole 30 ⟦Bone Fragments=Frammento d'Osso⟧.", "Il modello dell'armatura della Falce Ossuta di Don Julio richiede frammenti d'osso: un sacco di frammenti d'osso. Quei pazzi che si avventurano a Naxxramas mi forniscono abbastanza materiali di base per fabbricare l'armatura, ma sono sempre in cerca di altri frammenti d'osso del Flagello.\n\nAllora, che ne dici? Ti va di sporcarti le mani e intanto distruggere un po' di Flagello? Ci guadagniamo entrambi.", "Posso indicarti luoghi infestati dagli scheletri, {class}.", "Lavori in fretta, {name}. <Svelto/Svelta> come una volpe... Senti, ti ho mai raccontato di quando cantavo in un quartetto da barbiere?\n\nRicordami di raccontarti quella storia uno di questi giorni.", 0x9cb81398, 0xc7d45b70, 0x8dbeaf35, 0x3f157080, 0x2a565f14, "....." },
  [9128] = { "L'equazione elementale", "L'arcimaga Angela Dosantos alla ⟦Light's Hope Chapel=Cappella della Luce⟧, nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧, vuole 30 ⟦Core of Elements=Nucleo di Elementi⟧.", "Salute, <avventuriero/avventuriera>! Ti interessa un lavoro? Pago chi lavora per me con delle insegne. Queste insegne si possono spendere dal quartiermastro per acquistare oggetti potenti.\n\nTutto quello che devi fare è portarmi quanti più nuclei di elementi riesci a trasportare. Più sono, meglio è!\n\nLi troverai sugli elementali di ogni forma e dimensione che vivono nel nostro mondo.", "Posso solo indirizzarti nella giusta direzione, {name}.", "Ottimo lavoro, {name}! Come promesso, l'insegna è tua. Ricorda solo che ce ne sono altre...", 0x32fba198, 0x4e94c6b2, 0x711686a0, 0xe334f68d, 0xa886b3a1, "....." },
  [9131] = { "Assemblare l'Ardore", "Korfax alla ⟦Light's Hope Chapel=Cappella della Luce⟧, nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧, vuole 30 ⟦Dark Iron Scraps=Brandelli dei Ferroscuro⟧.", "Hai mai visto un'armatura dell'Ardore, {class}? No, certo che no. Sei ancora <un/una> <ragazzino/ragazzina>, <un/una> <moccioso/mocciosa>. Lascia che te lo dica: è magnifica.\n\nProbabilmente ti stai chiedendo cosa c'entri tutto questo con te, vero? Te lo dico io, <pivello/pivella>: mi servono brandelli dei ⟦Dark Iron=Ferroscuro⟧ e sono disposto a pagare per metterci le mani sopra, quanti più possibile.\n\nMi servono i brandelli per assemblare set dell'Ardore per i nostri campioni. Portami brandelli e verrai <pagato/pagata>.", "<Korfax ti ringhia contro.>\n\nChe vuoi? Indicazioni? Quelle posso dartele...", "Per ora può bastare. Se ne trovi altri, sai dove trovarmi.", 0xfcf29730, 0xc79083dc, 0xbec0de87, 0x56f85bce, 0x5422a5d8, ".....", nil, nil, 0x350c2585, nil, nil },
  [9136] = { "Flora selvaggia", "Rayne alla ⟦Light's Hope Chapel=Cappella della Luce⟧, nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧, vuole 30 Fronda Selvaggia.", "Fabbrico un tipo speciale di armatura per gli eroi coraggiosi che entrano a Naxxramas, nota come Vagasogni. Loro riescono a fornirmi la maggior parte dei materiali che mi servono, ma cerco sempre chi sappia raccogliere fronde selvagge dalla flora del nostro mondo.\n\nForse penserai che questo lavoro sia al di sotto di te, ma senza le fronde l'armatura non si potrebbe fare.\n\nInoltre mi trovo in una posizione particolare: posso pagarti con un'insegna a tua scelta, perché sia l'Alba sia la Crociata mi forniscono fondi.", "Conosco a fondo la flora del nostro mondo. Ti servono indicazioni?", "Ti sono molto obbligato, {name}.\n\n<Rayne si inchina.>\n\nRicorda che accetto sempre fronde.", 0x8bdd8753, 0x3bdb32cd, 0xf17f2db9, 0x23478164, 0xf8e6c80c, "....." },
  [9141] = { "Mi chiamano \"The Rooster\"", "Il comandante dei dispacci Metz alla ⟦Light's Hope Chapel=Cappella della Luce⟧, nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧, vuole un ⟦Argent Dawn Valor Token=Emblema del Valore dell'Alba d'Argento⟧.", "Vuoi un contratto? Cosa? Ti aspetti che ti consegni un ordine di lavoro richiestissimo solo perché ti sei <fatto/fatta> vedere? Non credo proprio, <pivello/pivella>. Artigiani da tutto il mondo si contendono i lavori qui al fronte.\n\nSe vuoi un ordine di lavoro, dovrai dimostrarmi che sei <disposto/disposta> a sanguinare per la causa. Portami un emblema del valore e ne parliamo.\n\nE c'è un solo modo per mettere quelle tue manacce sudicie da <pivello/pivella> su quegli emblemi: comincia ad ammazzare.", "<Il comandante Metz mastica il suo sigaro.>\n\nChe c'è? Sono un uomo impegnato.", "Bene, ecco come funziona: per ogni emblema del valore che consegni, ti do un altro contratto. Completi l'ordine scritto su quel contratto e consegni la merce al capocarovana Stonebruiser. Capito? Bene. Ora fuori dai piedi.", 0x29b5a92c, 0xfe328114, 0x27e4bb65, 0x652660a3, 0xf7b6fb79, "....." },
  [9153] = { "Sotto l'ombra", "Controlla la mappa per trovare una zona sotto attacco del Flagello. Va' laggiù e danneggia una necropoli sconfiggendo il Flagello che la circonda. Porta 10 Runa Necrotica al comandante Thomas Helleran alla ⟦Light's Hope Chapel=Cappella della Luce⟧, nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧.", "Le necropoli volanti del Flagello affliggono le terre dell'⟦Horde=Orda⟧ e dell'⟦Alliance=Alleanza⟧. Tanaris, le ⟦Blasted Lands=Terre Devastate⟧, ⟦Winterspring=Fontefredda⟧ e le ⟦Burning Steppes=Steppe Ardenti⟧ sono avvolte nell'ombra delle fortezze volanti.\n\nSolo unendo i nostri sforzi riusciremo a respingerle.\n\nLe necropoli sono sostenute da circoli magici in vari punti delle zone invase. Abbiamo stabilito che distruggere le orde senza mente che circondano questi circoli ne annienterà le difese.", "Ci vorrà tempo per avere la meglio su questa minaccia. Come te la sei cavata, {name}?", "Hai fatto un buon lavoro, {name}. Con queste sconfitte, una dopo l'altra, avremo la meglio su questa rinnovata minaccia del Flagello.\n\nRiposati e riprenditi, ma poi dovrai tornare al fronte, per non perdere il terreno che abbiamo guadagnato oggi.\n\nPer aiutarti nelle prossime battaglie, ti metteremo a disposizione alcuni dei nostri oggetti speciali in cambio di altre rune necrotiche.", 0x9e3cf3c9, 0x419ff114, 0x1788ecf5, 0x75ea4b6d, 0x0318842c, "....." },
  [9154] = { "⟦Light's Hope Chapel=Cappella della Luce⟧", "Consegna l'⟦Call to Arms Announcement=Annuncio della Chiamata alle Armi⟧ al Custode degli Archivi alla ⟦Light's Hope Chapel=Cappella della Luce⟧, nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧.", "Il Flagello è tornato, più numeroso che mai. L'⟦Argent Dawn=Alba d'Argento⟧ sta reclutando tutti gli uomini e le donne volenterosi e capaci, per difendere le nostre terre.\n\nSe condividi la nostra causa, porta questo documento al Custode degli Archivi alla ⟦Light's Hope Chapel=Cappella della Luce⟧, nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧.", "Sei <venuto/venuta> a unirti al nostro ordine, non è vero?", "L'⟦Argent Dawn=Alba d'Argento⟧ ha lanciato la chiamata d'aiuto e tu, insieme ad altri, hai risposto. Non abbiamo tempo per addestrarti. Riponiamo la nostra fiducia nelle tue capacità, e nel fatto che ti unirai a noi per ricacciare indietro questa minaccia del Flagello.", 0x0141f7a7, 0x3ddcc4ef, 0xf8db3513, 0xa0de5425, 0xb13b78e0, "....." },
  [9229] = { "Il ⟦Fate of Ramaladni=Destino di Ramaladni⟧", "Entra a Naxxramas e scopri il ⟦Fate of Ramaladni=Destino di Ramaladni⟧.", "Ramaladni era un guerriero della Confraternita, un allievo del gran signore Mograine prima ancora che l'Alba esistesse! Quando la notizia della morte di Mograine lo raggiunse, l'odio e la rabbia presero il sopravvento.\n\nCerca di capire, {name}: quando la rabbia e la vendetta prendono le redini, un uomo smette di essere un uomo. Diventa invece l'incarnazione delle emozioni che lo controllano. E così Ramaladni, lo spirito della vendetta, sarebbe entrato a Naxxramas per compiere la sua vendetta... senza fare mai ritorno.\n\nEntra a Naxxramas e scopri che fine ha fatto Ramaladni.", "Notizie di Ramaladni?", "È il suo anello! Ma è distrutto. Non è stata trovata nessun'altra traccia di Ramaladni?\n\n<Korfax fa una smorfia.>\n\nQuesto non promette nulla di buono per Ramaladni. L'anello, però... forse si può recuperare.", 0xfd5b4cde, 0xc5d447bd, 0x281d620a, 0xb8524c1a, 0xd438d4ec, "....." },
  [9230] = { "⟦Ramaladni's Icy Grasp=Anello Gelido di Ramaladni⟧", "Korfax alla ⟦Light's Hope Chapel=Cappella della Luce⟧, nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧, vuole che tu gli porti 1 ⟦Frozen Rune=Runa Congelata⟧, 1 ⟦Blue Sapphire=Zaffiro Blu⟧ e 1 ⟦Arcanite Bar=Lingotto d'Arcanite⟧.", "Riparare questo anello potrebbe rivelarsi piuttosto difficile, {name}. Vedi, è stato fatto con le stesse rune che si formano all'interno delle strutture del Flagello, come Naxxramas. Servono anche altri materiali, ma la tua preoccupazione principale dev'essere procurarti quelle rune congelate. Portami ciò che mi serve e riporterò l'anello al suo antico splendore.", "Le rune congelate si trovano probabilmente dentro Naxxramas.", "Nemmeno Ramaladni in persona avrebbe saputo fare di meglio! Ecco l'anello, come promesso.", 0x1cbb7bc6, 0x9a1c8800, 0x16dff9fa, 0x6e2af176, 0x6d0b2024, "....." },
  [9232] = { "L'unica canzone che conosco...", "L'artigiano Wilhelm alla ⟦Light's Hope Chapel=Cappella della Luce⟧, nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧, vuole che tu gli porti 2 Runa Congelata, 2 ⟦Essence of Water=Essenza d'Acqua⟧, 2 Zaffiro Blu e 30 monete d'oro.", "Ti senti una specie di eroe dell'Alba, eh? Ho visto i nostri soldati migliori farsi travolgere dalla plebaglia di Kel'Thuzad! Come potrebbe cavarsela a Naxxramas qualcuno così sprovveduto?\n\n<Wilhelm sospira.>\n\nBah, che scelta ho? Sei il meglio che posso trovare, tanto vale che ti aiuti.\n\nOmarion mi ha lasciato una sola ricetta. È l'unica canzone che conosco... Posso fare qualche variante di questi pantaloni; tu devi solo fornirmi i materiali.", "Non ti sei mica <imbattuto/imbattuta> in Omarion, vero?", "<Wilhelm si asciuga il sudore dalla fronte.>\n\nCe n'è voluto di lavoro! Goditi i pantaloni, {class}. Almeno adesso morirai con un paio pulito.", 0x519f4d00, 0x35595520, 0x146036e1, 0x8ad23295, 0x2677e2a7, "....." },
  [9233] = { "⟦Omarion's Handbook=Manuale di Omarion⟧", "Porta il ⟦Omarion's Handbook=Manuale di Omarion⟧ all'artigiano Wilhelm alla ⟦Light's Hope Chapel=Cappella della Luce⟧, nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧.", "Wilhelm,\n\nSe stai leggendo queste righe, sono morto. Finalmente. Voglio che tu sappia che i miei ultimi pensieri sono stati per te e per la tua incapacità nei mestieri. Purtroppo, chi ti porta questo manuale è messo ancora peggio di te in fatto di artigianato.\n\nQuanto al libro: queste sono le mie ricette rimanenti. Fabbrica al portatore di questo libro tutto ciò che chiede. Sono certo che farai pagare cara la tua opera perché, dopotutto, sei un bastardo.\n\nCon disprezzo,\n\nOmarion", "È quello che penso?\n\n<Wilhelm sembra sbavare.>", "Doveva essere proprio fuori di testa quando l'ha scritto! Omarion e io eravamo culo e camicia!\n\nComunque, questo apre di sicuro nuove possibilità, {name}. Ora posso fabbricare altri oggetti, in cambio di un piccolo compenso e del costo dei materiali, s'intende.", 0x5fd241d6, 0x0fa9fd4b, 0x7d852a96, 0xa5320578, 0xb4c95772, "....." },
  [9234] = { "⟦Icebane Gauntlets=Guanti Lunghi della Rovina dei Ghiacci⟧", "L'artigiano Wilhelm alla ⟦Light's Hope Chapel=Cappella della Luce⟧, nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧, vuole 5 Runa Congelata, 12 Lingotto di Torio, 2 Lingotto d'Arcanite, 2 Essenza d'Acqua e 200 monete d'oro.", "Grazie a te e a Omarion, che riposi in pace, ora sono in grado di creare i Guanti Lunghi della Rovina dei Ghiacci. Devi solo portarmi i materiali e pagare un piccolo compenso per la lavorazione.", "Hai portato i materiali?", "Ecco il tuo ordine, {name}. Consegnato come promesso!", 0xb1ff7de5, 0x6c1d4b30, 0x26bc0f93, 0x0d86390a, 0xce411185, "....." },
  [9235] = { "⟦Icebane Bracers=Bracciali della Rovina dei Ghiacci⟧", "L'artigiano Wilhelm alla ⟦Light's Hope Chapel=Cappella della Luce⟧, nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧, vuole 4 Runa Congelata, 12 Lingotto di Torio, 2 Lingotto d'Arcanite, 2 ⟦Essence of Water=Essenza d'Acqua⟧ e 200 monete d'oro.", "Grazie a te e a Omarion, che riposi in pace, ora sono in grado di creare i Bracciali della Rovina dei Ghiacci. Devi solo portarmi i materiali e pagare un piccolo compenso per la lavorazione.", "Hai portato i materiali?", "Ecco il tuo ordine, {name}. Consegnato come promesso!", 0x63cca747, 0x1260a20e, 0xf077fcb1, 0x0d86390a, 0xce411185, "....." },
  [9236] = { "⟦Icebane Breastplate=Pettorale Corazzato della Rovina dei Ghiacci⟧", "L'artigiano Wilhelm alla ⟦Light's Hope Chapel=Cappella della Luce⟧, nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧, vuole 8 Runa Congelata, 16 Lingotto di Torio, 2 Lingotto d'Arcanite, 4 ⟦Essence of Water=Essenza d'Acqua⟧ e 300 monete d'oro. Dovrai anche avere reputazione Osannato presso l'⟦Argent Dawn=Alba d'Argento⟧.", "Grazie a te e a Omarion, che riposi in pace, ora sono in grado di creare un Pettorale Corazzato della Rovina dei Ghiacci. Devi solo portarmi i materiali e pagare un piccolo compenso per la lavorazione.", "Hai portato i materiali?", "Ecco il tuo ordine, {name}. Consegnato come promesso!", 0x4e2bceaa, 0xfc110014, 0xa8b406d7, 0x0d86390a, 0xce411185, "....." },
  [9237] = { "⟦Glacial Cloak=Mantello Glaciale⟧", "L'artigiano Wilhelm alla ⟦Light's Hope Chapel=Cappella della Luce⟧, nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧, vuole 5 Runa Congelata, 4 Rotolo di Telarunica, 2 Essenza d'Acqua, 4 Seta Ferrosa di Ragno e 200 monete d'oro. Devi anche avere reputazione Osannato presso l'⟦Argent Dawn=Alba d'Argento⟧.", "Grazie a te e a Omarion, che riposi in pace, ora sono in grado di creare un Mantello Glaciale. Devi solo portarmi i materiali e pagare un piccolo compenso per la lavorazione.", "Hai portato i materiali?", "Ecco il tuo ordine, {name}. Consegnato come promesso!", 0x18004bb0, 0x1f37eaae, 0x4cb81801, 0x0d86390a, 0xce411185, "....." },
  [9238] = { "⟦Glacial Wrists=Polsiere Glaciali⟧", "L'artigiano Wilhelm alla ⟦Light's Hope Chapel=Cappella della Luce⟧, nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧, vuole 4 Runa Congelata, 2 Rotolo di Telarunica, 2 Essenza d'Acqua, 2 Seta Ferrosa di Ragno e 200 monete d'oro.", "Grazie a te e a Omarion, che riposi in pace, ora sono in grado di creare le Polsiere Glaciali. Devi solo portarmi i materiali e pagare un piccolo compenso per la lavorazione.", nil, "Ecco una faccia che non mi aspettavo di rivedere così presto.\n\nQuesta è davvero una bella notizia, {name}, in più modi di quanto tu possa immaginare.", 0x5705d3c0, 0xc3e58102, 0xc5358afd, nil, 0x9f82796e, "...m." },
  [9239] = { "⟦Glacial Gloves=Guanti Glaciali⟧", "L'artigiano Wilhelm alla ⟦Light's Hope Chapel=Cappella della Luce⟧, nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧, vuole 5 Runa Congelata, 4 Rotolo di Telarunica, 4 Essenza d'Acqua, 2 Seta Ferrosa di Ragno e 200 monete d'oro.", "Grazie a te e a Omarion, che riposi in pace, ora sono in grado di creare i Guanti Glaciali. Devi solo portarmi i materiali e pagare un piccolo compenso per la lavorazione.", "Hai portato i materiali?", "Ecco il tuo ordine, {name}. Consegnato come promesso!", 0x363d66ea, 0xba017235, 0x3792ae76, 0x0d86390a, 0xce411185, "....." },
  [9240] = { "⟦Glacial Vest=Veste Glaciale⟧", "L'artigiano Wilhelm alla ⟦Light's Hope Chapel=Cappella della Luce⟧, nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧, vuole 8 Runa Congelata, 8 Rotolo di Telarunica, 6 Essenza d'Acqua, 4 Seta Ferrosa di Ragno e 300 monete d'oro. Devi anche avere reputazione Osannato presso l'⟦Argent Dawn=Alba d'Argento⟧.", "Grazie a te e a Omarion, che riposi in pace, ora sono in grado di creare una Veste Glaciale. Devi solo portarmi i materiali e pagare un piccolo compenso per la lavorazione.", "Hai portato i materiali?", "Ecco il tuo ordine, {name}. Consegnato come promesso!", 0xd3d23e1b, 0xcd82a11e, 0xc8a26e31, 0x0d86390a, 0xce411185, "....." },
  [9241] = { "⟦Polar Bracers=Bracciali Polari⟧", "L'artigiano Wilhelm alla ⟦Light's Hope Chapel=Cappella della Luce⟧, nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧, vuole 4 Runa Congelata, 12 ⟦Enchanted Leather=Cuoio Incantato⟧, 3 ⟦Essence of Water=Essenza d'Acqua⟧, 3 Pelle Dura Trattata e 200 monete d'oro.", "Grazie a te e a Omarion, che riposi in pace, ora sono in grado di creare i Bracciali Polari. Devi solo portarmi i materiali e pagare un piccolo compenso per la lavorazione.", "Hai portato i materiali?", "Ecco il tuo ordine, {name}. Consegnato come promesso!", 0x1f8f20b8, 0xab2116f4, 0xdd632e6d, 0x0d86390a, 0xce411185, "....." },
