  [9245] = { "⟦Icy Scale Gauntlets=Guanti Lunghi di Scaglie Ghiacciate⟧", "L'artigiano Wilhelm alla ⟦Light's Hope Chapel=Cappella della Luce⟧, nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧, vuole 5 Runa Congelata, 16 ⟦Heavy Scorpid Scale=Scaglie Pesanti di Scorpide⟧, 5 ⟦Essence of Water=Essenza d'Acqua⟧, 3 Pelle Dura Trattata e 200 monete d'oro.", "Grazie a te e a Omarion, che riposi in pace, ora sono in grado di creare i Guanti Lunghi di Scaglie Ghiacciate. Devi solo portarmi i materiali e pagare un piccolo compenso per la lavorazione.", "Hai portato i materiali?", "Ecco il tuo ordine, {name}. Consegnato come promesso!", 0xf27864b3, 0xcb09217c, 0x92db9c3b, 0x0d86390a, 0xce411185, "....." },
  [9246] = { "⟦Icy Scale Breastplate=Pettorale Corazzato di Scaglie Ghiacciate⟧", "L'artigiano Wilhelm alla ⟦Light's Hope Chapel=Cappella della Luce⟧, nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧, vuole 8 Runa Congelata, 24 ⟦Heavy Scorpid Scale=Scaglie Pesanti di Scorpide⟧, 7 ⟦Essence of Water=Essenza d'Acqua⟧, 5 Pelle Dura Trattata e 300 monete d'oro. Devi anche avere reputazione Osannato presso l'⟦Argent Dawn=Alba d'Argento⟧.", "Grazie a te e a Omarion, che riposi in pace, ora sono in grado di creare un Pettorale Corazzato di Scaglie Ghiacciate. Devi solo portarmi i materiali e pagare un piccolo compenso per la lavorazione.", "Hai portato i materiali?", "Ecco il tuo ordine, {name}. Consegnato come promesso!", 0x36d42a52, 0xee8d4219, 0xe98d75d0, 0x0d86390a, 0xce411185, "....." },
  [9247] = { "La chiamata del custode", "Porta la Lettera dal Custode degli Archivi al Custode stesso, alla ⟦Light's Hope Chapel=Cappella della Luce⟧, nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧.", "{name},\n\nIn passato hai servito gli interessi dell'⟦Argent Dawn=Alba d'Argento⟧, sempre al meglio delle tue capacità. Ora, ancora una volta, suoniamo la chiamata alle armi, nel momento del nostro più grande bisogno.\n\n{name}, presentati al Custode degli Archivi alla ⟦Light's Hope Chapel=Cappella della Luce⟧, nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧, se sei <disposto/disposta> ad aiutarci ancora una volta.", nil, nil, 0xe8f9010e, 0x24d23469, 0x455bb082, nil, nil, "...mm" },
  [9248] = { "Un'umile offerta", "Aurel Goldleaf, alla ⟦Cenarion Hold=Fortezza Cenariana⟧ in ⟦Silithus=Silitus⟧, vuole che tu le porti 1 ⟦Abyssal Scepter=Scettro Abissale⟧. Devi anche essere Onorato presso il ⟦Cenarion Circle=Circolo Cenariano⟧.", "Ishnu-alah, {race}. Mostrami la prova della morte di un signore dell'Abyssal Council e ti ricompenserò con un oggetto che dovrebbe aiutarti nelle tue battaglie contro i Qiraji.", "Fandu-dath-belore? Oh, perdonami, {name}. Non ti avevo <riconosciuto/riconosciuta>. Hai lo scettro?", "Ande'thoras-ethil. Nella mia lingua natale significa: «Che i tuoi affanni siano alleviati».\n\nIndossa l'anello con orgoglio e in buona salute, {name}.", 0xfd579dde, 0xcb666c32, 0x5dee4073, 0x6b22398a, 0x4faf4b72, "....." },
  [9250] = { "⟦Frame of Atiesh=Corpo di Atiesh⟧", "Trova qualcuno che ti aiuti a recuperare gli ultimi due pezzi del bastone e a liberarlo dal male.", "Ora che il corpo è formato, Atiesh è quasi integra. Mancano solo la testa e la base del bastone. C'è anche un piccolo problema: il bastone è un tramite per il male di Sargeras.\n\nTrova qualcuno che possa aiutarti a recuperare i pezzi mancanti e a esorcizzare il male dal bastone.", "Era giunta la sua ora, mortale.", "Gli arcimaghi sono morti.\n\nNon piangere la loro scomparsa, {name}. Tutte queste cose sono volute dal destino. Proprio come era destino che tu impugnassi il bastone del Guardiano...", 0xf653c43a, 0x408b91b7, 0x2be6e916, 0x6bb260cc, 0xebb1066f, "....." },
  [9251] = { "Atiesh, il granbastone contaminato", "Anachronos, alle ⟦Caverns of Time=Caverne del Tempo⟧ a Tanaris, vuole la ⟦Staff Head of Atiesh=Testa di Atiesh⟧ e la ⟦Base of Atiesh=Base di Atiesh⟧.", "Ti chiedi perché tu sia ancora <vivo/viva>. Dopotutto, possiedi un oggetto di grande malvagità. La risposta non è chiara, {name}. Io faccio solo ciò che devo.\n\nKel'Thuzad siede sul suo trono a Naxxramas, e trama... Cerca ciò che tu possiedi e possiede ciò che tu cerchi.\n\nQuanto alla base del bastone, il nano Brann Bronzebeard l'aveva con sé quando entrò ad ⟦Ahn'Qiraj=Ahn'qiraj⟧. Lui ha lasciato ⟦Ahn'Qiraj=Ahn'qiraj⟧, ma la base di Atiesh è rimasta lì.\n\nSe riuscirai a recuperare i pezzi, riportameli.", "Nella sua forma attuale, il bastone è troppo pericoloso per stare nelle mani di un mortale.", "C'è un essere al suo interno... un essere che non è di questo mondo.", 0xcd0ba26f, 0xd3abd03c, 0xf57ef0e6, 0x6141889a, 0x8e96d632, "....." },
  [9257] = { "⟦Atiesh, Greatstaff of the Guardian=Atiesh, Granbastone del Guardiano⟧", "Anachronos, alle ⟦Caverns of Time=Caverne del Tempo⟧ a Tanaris, vuole che tu porti ⟦Atiesh, Greatstaff of the Guardian=Atiesh, Granbastone del Guardiano⟧ a Stratholme e la usi sulla Consecrated Earth. Sconfiggi l'entità esorcizzata dal bastone e torna da lui.", "Quest'ultimo compito sarà il più difficile di tutti, {name}. Hai affrontato e sconfitto sia un Dio Antico sia il generale del Re dei Lich, ma ora devi affrontare la mano di Sargeras.\n\nPorta il bastone a Stratholme. Lì troverai un lembo di terra consacrata: il suolo dove furono assassinati i più grandi cavalieri di Lordaeron. Posa il bastone contaminato sul suolo sacro e preparati: un'entità di immenso potere ne uscirà... Sconfiggi l'essere demoniaco che controlla il bastone e torna da me.", "Non devo interferire, {race}.", "La grandezza di questa impresa non va sottovalutata, {name}. Hai fatto ciò che quasi tutti avrebbero ritenuto impossibile. Ahimè, era destino. Il bastone ha fatto la sua scelta...", 0x9b7c702f, 0xc82f289b, 0xe69efe9d, 0x6241b6f1, 0xc81ee3eb, "....." },
  [9260] = { "Indagare sul Flagello a ⟦Stormwind=Roccavento⟧", "Raccogli 3 Pietra Necrotica Confusa dal Flagello fuori ⟦Stormwind=Roccavento⟧ e indaga sui cerchi runici luminosi vicino al loro accampamento.", "Il Flagello si è accampato proprio alle nostre porte: non possiamo restare con le mani in mano! Di certo ti farai avanti per difendere ⟦Stormwind=Roccavento⟧ da questi maledetti invasori?\n\nLà fuori ci sono strani cerchi runici, che brillano della stessa energia che circonda i non morti e la Necropoli lassù. Hanno un significato, ne sono certo, e voglio che tu scopra quale. Già che ci sei, sfoltisci le file di quegli abomini; portami la prova della loro morte insieme ai tuoi risultati e ti ricompenserò. Va'!", "Hai già indagato sull'invasione? Non c'è tempo da perdere!", "Mmm. Da ciò che mi hai detto, le voci dentro i cerchi... devono servire a comunicare in qualche modo. Rabbrividisco al pensiero di quali menti innaturali vengano contattate con una simile magia. In ogni caso, sembri esserne <uscito/uscita> <integro/integra> e <sano/sana> di mente. L'⟦Argent Dawn=Alba d'Argento⟧ apprezza il tuo servizio.", 0x00e4dbef, 0x9dc15400, 0x584b0283, 0x5ea2db66, 0x4f3229e9, "....." },
  [9261] = { "Indagine sul Flagello a ⟦Ironforge=Forgiardente⟧", "Raccogli tre Pietra Necrotica Confusa dal Flagello fuori da ⟦Ironforge=Forgiardente⟧ e indaga sui cerchi runici luminosi vicino al loro accampamento.", "Il Flagello si è accampato proprio alle nostre porte: non possiamo restare con le mani in mano! Di certo ti farai avanti per difendere ⟦Ironforge=Forgiardente⟧ da questi invasori maledetti?\n\nLà fuori ci sono strani cerchi runici, che brillano della stessa energia che circonda i non morti e la Necropoli lassù. Hanno un significato, ne sono certo, e voglio che tu scopra quale. Già che ci sei, sfoltisci le file di quegli abomini; portami la prova della loro morte insieme ai tuoi risultati e ti ricompenserò. Va'!", "Hai già indagato sull'invasione? Non c'è tempo da perdere!", "Mmm. Da ciò che mi hai detto, le voci dentro i cerchi... devono servire a comunicare in qualche modo. Rabbrividisco al pensiero di quali menti innaturali vengano contattate con una simile magia. In ogni caso, sembri esserne <uscito/uscita> <integro/integra> e <sano/sana> di mente. L'⟦Argent Dawn=Alba d'Argento⟧ apprezza il tuo servizio.", 0x71257d44, 0x40d576b1, 0x6d9b70a9, 0x5ea2db66, 0x4f3229e9, "....." },
  [9262] = { "Indagine sul Flagello a Darnassus", "Raccogli tre Pietra Necrotica Confusa dal Flagello fuori da Darnassus e indaga sui cerchi runici luminosi vicino al loro accampamento.", "Il Flagello si è accampato proprio alle nostre porte: non possiamo restare con le mani in mano! Di certo ti farai avanti per difendere Darnassus da questi invasori maledetti?\n\nLà fuori ci sono strani cerchi runici, che brillano della stessa energia che circonda i non morti e la Necropoli lassù. Hanno un significato, ne sono certo, e voglio che tu scopra quale. Già che ci sei, sfoltisci le file di quegli abomini; portami la prova della loro morte insieme ai tuoi risultati e ti ricompenserò. Va'!", "Hai già indagato sull'invasione? Non c'è tempo da perdere!", "Mmm. Da ciò che mi hai detto, le voci dentro i cerchi... devono servire a comunicare in qualche modo. Rabbrividisco al pensiero di quali menti innaturali vengano contattate con una simile magia. In ogni caso, sembri esserne <uscito/uscita> <integro/integra> e <sano/sana> di mente. L'⟦Argent Dawn=Alba d'Argento⟧ apprezza il tuo servizio.", 0xae0b4b57, 0x8c429383, 0x2683cc59, 0x5ea2db66, 0x4f3229e9, "....." },
  [9263] = { "Indagine sul Flagello a Orgrimmar", "Raccogli tre Pietra Necrotica Confusa dal Flagello fuori da Orgrimmar e indaga sui cerchi runici luminosi vicino al loro accampamento.", "Il Flagello si è accampato proprio alle nostre porte: non possiamo restare con le mani in mano! Di certo ti farai avanti per difendere Orgrimmar da questi invasori maledetti?\n\nLà fuori ci sono strani cerchi runici, che brillano della stessa energia che circonda i non morti e la Necropoli lassù. Hanno un significato, ne sono certo, e voglio che tu scopra quale. Già che ci sei, sfoltisci le file di quegli abomini; portami la prova della loro morte insieme ai tuoi risultati e ti ricompenserò. Va'!", "Hai già indagato sull'invasione? Non c'è tempo da perdere!", "Mmm. Da ciò che mi hai detto, le voci dentro i cerchi... devono servire a comunicare in qualche modo. Rabbrividisco al pensiero di quali menti innaturali vengano contattate con una simile magia. In ogni caso, sembri esserne <uscito/uscita> <integro/integra> e <sano/sana> di mente. L'⟦Argent Dawn=Alba d'Argento⟧ apprezza il tuo servizio.", 0xa887c042, 0xed596569, 0x4535136d, 0x5ea2db66, 0x4f3229e9, "....." },
  [9264] = { "Indagine sul Flagello a ⟦Thunder Bluff=Picco del Tuono⟧", "Raccogli tre Pietra Necrotica Confusa dal Flagello fuori da ⟦Thunder Bluff=Picco del Tuono⟧ e indaga sui cerchi runici luminosi vicino al loro accampamento.", "Il Flagello si è accampato proprio alle nostre porte: non possiamo restare con le mani in mano! Di certo ti farai avanti per difendere ⟦Thunder Bluff=Picco del Tuono⟧ da questi invasori maledetti?\n\nLà fuori ci sono strani cerchi runici, che brillano della stessa energia che circonda i non morti e la Necropoli lassù. Hanno un significato, ne sono certo, e voglio che tu scopra quale. Già che ci sei, sfoltisci le file di quegli abomini; portami la prova della loro morte insieme ai tuoi risultati e ti ricompenserò. Va'!", "Hai già indagato sull'invasione? Non c'è tempo da perdere!", "Mmm. Da ciò che mi hai detto, le voci dentro i cerchi... devono servire a comunicare in qualche modo. Rabbrividisco al pensiero di quali menti innaturali vengano contattate con una simile magia. In ogni caso, sembri esserne <uscito/uscita> <integro/integra> e <sano/sana> di mente. L'⟦Argent Dawn=Alba d'Argento⟧ apprezza il tuo servizio.", 0xa9531e97, 0x64454a5d, 0xb814786e, 0x5ea2db66, 0x4f3229e9, "....." },
  [9265] = { "Indagine sul Flagello di ⟦Undercity=Sepulcra⟧", "Raccogli tre Pietra Necrotica Confusa dal Flagello fuori da ⟦Undercity=Sepulcra⟧ e indaga sui cerchi runici luminosi vicino al loro accampamento.", "Il Flagello si è accampato proprio alle nostre porte; non possiamo restare con le mani in mano! Di certo ti farai avanti per difendere ⟦Undercity=Sepulcra⟧ da questi maledetti invasori, vero?\n\nLà fuori ci sono strani cerchi runici, che brillano della stessa energia che circonda i non morti e la Necropoli sopra di noi. Hanno un significato, ne sono certo, e voglio che tu scopra quale. Già che ci sei, sfoltisci le file di quegli abomini; portami la prova della loro morte insieme ai tuoi risultati e ti ricompenserò. Va'!", "Hai già indagato sull'invasione? Non c'è tempo da perdere!", "Mmm. Da ciò che mi hai detto, le voci dentro i cerchi... devono servire a comunicare in qualche modo. Rabbrividisco al pensiero di quali menti innaturali vengano contattate con una simile magia. In ogni caso, sembri esserne <uscito/uscita> <integro/integra> e <sano/sana> di mente. L'⟦Argent Dawn=Alba d'Argento⟧ apprezza il tuo servizio.", 0xe8ce843e, 0xae694c31, 0xcdb468ae, 0x5ea2db66, 0x4f3229e9, "....." },
  [9269] = { "⟦Atiesh, Greatstaff of the Guardian=Atiesh, Granbastone del Guardiano⟧", "Anachronos, alle ⟦Caverns of Time=Caverne del Tempo⟧ a Tanaris, vuole che tu porti ⟦Atiesh, Greatstaff of the Guardian=Atiesh, Granbastone del Guardiano⟧ a Stratholme e la usi sulla Consecrated Earth. Sconfiggi l'entità esorcizzata dal bastone e torna da lui.", "Quest'ultimo compito sarà il più difficile di tutti, {name}. Hai affrontato e sconfitto sia un Dio Antico sia il generale del Re dei Lich, ma ora devi affrontare la mano di Sargeras.\n\nPorta il bastone a Stratholme. Lì troverai un lembo di terra consacrata: il suolo dove furono assassinati i più grandi cavalieri di Lordaeron. Posa il bastone contaminato sul suolo sacro e preparati: un'entità di immenso potere ne uscirà... Sconfiggi l'essere demoniaco che controlla il bastone e torna da me.", "Non devo interferire, {race}.", "La grandezza di questa impresa non va sottovalutata, {name}. Hai fatto ciò che quasi tutti avrebbero ritenuto impossibile. Ahimè, era destino. Il bastone ha fatto la sua scelta...", 0x9b7c702f, 0xc82f289b, 0xe69efe9d, 0x6241b6f1, 0xc81ee3eb, "....." },
