  [9272] = { "Vestirsi per la parte", nil, nil, nil, "Yarrr... se ci tieni a goderti la compagnia di noi vecchi lupi di mare, faresti meglio a smettere di vestirti come un furfante! Ecco, mettiti addosso qualcosa di decente prima che ti faccia passare sotto la chiglia.\n\nQuesti ti staranno meglio di quanto siano mai stati a quel vecchio cane di Red-Eyed Ben. L'ho perso in mare, in una tempesta infernale.\n\nPortali con orgoglio, compare!", 0x09338667, nil, nil, nil, 0x35e4428b, ".mmm." },
  [9273] = { "Riscatta il ⟦iCoke Prize Voucher=Buono Premio iCola⟧", nil, nil, nil, nil, 0xfd599f6c, nil, nil, nil, nil, ".mmmm" },
  [9292] = { "⟦Cracked Necrotic Crystal=Cristallo Necrotico Infranto⟧", "Porta il ⟦Cracked Necrotic Crystal=Cristallo Necrotico Infranto⟧ al tenente Orrin, fuori dalle porte di ⟦Stormwind=Roccavento⟧.", "Sul cadavere dell'abominio caduto trovi un cristallo incrinato, che pulsa lentamente di energia necrotica.", "Ti serve qualcosa?", "Mm, l'hai preso dal cadavere di uno degli abomini invasori?\n\nAbbiamo ricevuto notizie degli accampamenti delle necropoli che il Flagello sta evocando. Sospetto che volessero crearne uno dentro ⟦Stormwind=Roccavento⟧. Per fortuna non ci sono riusciti.", 0x50e85762, 0x78ac8cb0, 0xfb485a40, 0x05240edc, 0x92f243ce, "....." },
  [9295] = { "⟦Letter from the Front=Lettera dal Fronte⟧", "Porta la Torn Letter al Custode degli Archivi alla ⟦Light's Hope Chapel=Cappella della Luce⟧, nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧.", "Hai trovato questa lettera su uno dei tanti servitori del Flagello che hai ucciso. Dall'aspetto e dall'odore, è rimasta a lungo tra i non morti. Forse qualcuno alla ⟦Light's Hope Chapel=Cappella della Luce⟧ sarebbe interessato a esaminarla più a fondo...", "Sì? Cos'hai lì?", "Che tragedia. Queste parole, chiaramente destinate a qualcuno che il soldato amava, non sono mai arrivate a destinazione. I fatti descritti risalgono ad anni fa; non so se il destinatario sia ancora vivo.\n\nC'è ancora speranza, però. Con i nomi e le informazioni che fornisce, potrei riuscire a rintracciare la famiglia! Ci vorrà qualche ricerca, ma il bibliotecario di ⟦Stormwind=Roccavento⟧ mi deve un favore...\n\nGrazie per avermela portata. Con il tuo aiuto, forse potremo finalmente dare un po' di pace a qualcuno.", 0x96157b4a, 0xc88064df, 0x43325f84, 0xf8d5b5af, 0xf0bfe43f, "....." },
  [9299] = { "Nota dal fronte", "Porta la Careworn Note al Custode degli Archivi alla ⟦Light's Hope Chapel=Cappella della Luce⟧, nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧.", "Hai trovato questa lettera su uno dei tanti servitori del Flagello che hai ucciso. Dall'aspetto e dall'odore, è rimasta a lungo tra i non morti. Forse qualcuno alla ⟦Light's Hope Chapel=Cappella della Luce⟧ sarebbe interessato a esaminarla più a fondo...", "Sì? Cos'hai lì?", "Che tragedia. Queste parole, chiaramente destinate a qualcuno che il soldato amava, non sono mai arrivate a destinazione. I fatti descritti risalgono ad anni fa; non so se il destinatario sia ancora vivo.\n\nC'è ancora speranza, però. Con i nomi e le informazioni che fornisce, potrei riuscire a rintracciare la famiglia! Ci vorrà qualche ricerca, ma il bibliotecario di ⟦Stormwind=Roccavento⟧ mi deve un favore...\n\nGrazie per avermela portata. Con il tuo aiuto, forse potremo finalmente dare un po' di pace a qualcuno.", 0xe162fd2c, 0xeb1d0cfc, 0x43325f84, 0xf8d5b5af, 0xf0bfe43f, "....." },
