  [9302] = { "Una missiva dal fronte", "Porta la Crumpled Missive al Custode degli Archivi alla ⟦Light's Hope Chapel=Cappella della Luce⟧, nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧.", "Hai trovato questa lettera su uno dei tanti servitori del Flagello che hai ucciso. Dall'aspetto e dall'odore, è rimasta a lungo tra i non morti. Forse qualcuno alla ⟦Light's Hope Chapel=Cappella della Luce⟧ sarebbe interessato a esaminarla più a fondo...", "Sì? Cos'hai lì?", "Che tragedia. Queste parole, chiaramente destinate a qualcuno che il soldato amava, non sono mai arrivate a destinazione. I fatti descritti risalgono ad anni fa; non so se il destinatario sia ancora vivo.\n\nC'è ancora speranza, però. Con i nomi e le informazioni che fornisce, potrei riuscire a rintracciare la famiglia! Ci vorrà qualche ricerca, ma il bibliotecario di ⟦Stormwind=Roccavento⟧ mi deve un favore...\n\nGrazie per avermela portata. Con il tuo aiuto, forse potremo finalmente dare un po' di pace a qualcuno.", 0xd5e14e2f, 0xdc92c168, 0x43325f84, 0xf8d5b5af, 0xf0bfe43f, "....." },
  [9304] = { "Un documento dal fronte", "Porta lo Smudged Document al Custode degli Archivi alla ⟦Light's Hope Chapel=Cappella della Luce⟧, nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧.", "Hai trovato questa lettera su uno dei tanti servitori del Flagello che hai ucciso. Dall'aspetto e dall'odore, è rimasta a lungo tra i non morti. Forse qualcuno alla ⟦Light's Hope Chapel=Cappella della Luce⟧ sarebbe interessato a esaminarla più a fondo...", "Sì? Cos'hai lì?", "Che tragedia. Queste parole, chiaramente destinate a qualcuno che il soldato amava, non sono mai arrivate a destinazione. I fatti descritti risalgono ad anni fa; non so se il destinatario sia ancora vivo.\n\nC'è ancora speranza, però. Con i nomi e le informazioni che fornisce, potrei riuscire a rintracciare la famiglia! Ci vorrà qualche ricerca, ma il bibliotecario di ⟦Stormwind=Roccavento⟧ mi deve un favore...\n\nGrazie per avermela portata. Con il tuo aiuto, forse potremo finalmente dare un po' di pace a qualcuno.", 0xabec2052, 0xe8881a90, 0x43325f84, 0xf8d5b5af, 0xf0bfe43f, "....." },
  [9310] = { "⟦Faint Necrotic Crystal=Cristallo Necrotico Debole⟧", "Porta il ⟦Faint Necrotic Crystal=Cristallo Necrotico Debole⟧ al tenente Rukag, nel cortile di ⟦Undercity=Sepulcra⟧.", "Sul cadavere dello spettro abbattuto trovi un cristallo che irradia debolmente energia necrotica.", "Posso aiutarti?", "Dici che l'hai preso da uno spettro che attaccava la città?\n\nAbbiamo ricevuto notizie degli accampamenti delle necropoli che il Flagello sta evocando. Sospetto che volessero crearne uno a ⟦Undercity=Sepulcra⟧. In futuro dovremo stare all'erta.", 0xe2cc3f91, 0x78a121b3, 0x83ff7c6c, 0xc8eedeb3, 0x57dd511f, "....." },
  [9319] = { "Una luce nei luoghi oscuri", "Trova e tocca i falò dei ⟦Blackrock Spire=Bastioni di Roccianera⟧, di ⟦Dire Maul=Maglio Infausto⟧, di Scholomance e di Stratholme, poi torna dal custode della fiamma della festa.", "Non siamo i soli a celebrare questa festa, {name}. Tutte le creature, tutte le culture sono toccate dalla fiamma. Anche nei luoghi più oscuri si accendono i fuochi.\n\nSe vuoi vederli con i tuoi occhi, scendi nelle profondità. Cerca i falò che ardono a Stratholme, a Scholomance, tra gli ogre di ⟦Dire Maul=Maglio Infausto⟧ e nelle sale degli stessi ⟦Blackrock Spire=Bastioni di Roccianera⟧. Attenderò il tuo ritorno.", "Hai trovato la strada nell'oscurità?", "La tua essenza canta dell'energia delle fiamme che hai trovato, {name}. Il fuoco che hai incontrato è potente e, con le giuste conoscenze, il suo potere si può imbrigliare...\n\n<Il custode della fiamma mormora un incantesimo in una strana lingua arcana, poi tira fuori una bottiglia luminosa.>\n\nAh! Eccoci. Che possa illuminare il tuo cammino, ovunque tu vada.", 0xc7993864, 0x71f9855e, 0x22e1d9d3, 0x6fd59256, 0xb63b325f, "....." },
  [9322] = { "Fuochi selvaggi su Kalimdor", "Visita gli accampamenti di Mezza Estate ad Azshara, a ⟦Silithus=Silitus⟧, nel ⟦Un'Goro Crater=Cratere di Un'Goro⟧ e a ⟦Winterspring=Fontefredda⟧, poi torna dal custode della fiamma della festa.", "I Fuochi di Mezza Estate si celebrano ovunque su Azeroth, e la variegata terra di Kalimdor non fa eccezione. Mi sembri in forma per viaggiare: forse è il momento di partire.\n\nLa Mezza Estate non si può apprezzare davvero se non hai visto gli ardenti fuochi blu in terre lontane. I celebranti hanno acceso fuochi nella gelida ⟦Winterspring=Fontefredda⟧ occidentale, nel nord-est di Azshara, vicino all'⟦Valor's Rest=Asilo dei Valorosi⟧ nelle lande desolate di ⟦Silithus=Silitus⟧ e all'ingresso del rigoglioso Un'Goro. Torna quando il tuo viaggio sarà concluso.", "Le fiamme di Kalimdor ardono luminose?", "Il tuo spirito risplende del calore dei fuochi di Kalimdor, amico. Non è corroborante, questo calore?\n\nQuando il potere svanirà da te, forse questi ti aiuteranno a riaccendere la sensazione.", 0x515e7ab2, 0x3a2cca60, 0xdeb42c6f, 0xe9989baa, 0x1254be4d, "....." },
  [9323] = { "Fuochi selvaggi nei Regni Orientali", "Visita gli accampamenti dei Fuochi di Mezza Estate nelle ⟦Blasted Lands=Terre Devastate⟧, nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧, nelle Entroterre e nella ⟦Searing Gorge=Gorgia Rovente⟧, poi parla con il custode della fiamma della festa.", "La nostra celebrazione della fiamma si estende per tutta la terra, {class}. Non c'è un solo luogo che il calore di questa festa non abbia toccato, e i fuochi più forti ardono di un blu brillante. Cercali.\n\nNe troverai uno appena a nord dei ⟦Blackrock Spire=Bastioni di Roccianera⟧. Gli altri si trovano nel cuore delle ⟦Eastern Plaguelands=Terre Infette Orientali⟧ vicino a una città in rovina, lungo la strada verso le scogliere delle montuose Entroterre e sulla via per il Portale Oscuro nelle ⟦Blasted Lands=Terre Devastate⟧.\n\nTorna quando il tuo viaggio sarà finito.", "Hai già percorso il continente? L'illuminazione ti attende.", "Ah, eccoti qui. Un po' più stanc<o/a>, un po' più impolverat<o/a>, ma illuminat<o/a>! In questa stagione il calore ci tocca tutti e ci unisce; tutto il tuo essere risplende del potere dei fuochi che hai toccato.\n\nAh, ma di questi tempi l'illuminazione è una ricompensa piuttosto misera per chi viene mandato a svolgere un compito, immagino. Prendi questi, allora, e goditi la festa.", 0xb359bc1c, 0x1068f8e8, 0x3aadd8f0, 0x12c78f6d, 0x04028424, "....." },
  [9324] = { "Rubare la Fiamma di Orgrimmar", "Riporta la ⟦Flame of Orgrimmar=Fiamma di Orgrimmar⟧ al sapiente della festa.", "Questa fiamma, rubata dal cuore stesso di Orgrimmar, ti inonda di calore. Questo potere primordiale ti è estraneo, ma il sapiente potrebbe saperne di più...", "Sembri quasi risplendere, {race}. Che cos'hai lì?", "Che cos'è questa? Se non sbaglio, questa fiamma è stata presa dal cuore stesso di Orgrimmar! Nel suo calore rovente si riflettono i cuori fieri degli orchi e dei troll. Che bella aggiunta alla nostra collezione: quanto coraggio, intrufolarsi nella tana del nemico per recuperare la fiamma sacra!", 0x6060e294, 0x2c3b06e5, 0xa233ef98, 0x35bceb01, 0xb78afa9a, "....." },
  [9325] = { "Rubare la Fiamma di Picco del Tuono", "Riporta la ⟦Flame of Thunder Bluff=Fiamma di Picco del Tuono⟧ al sapiente della festa.", "Questa fiamma, rubata agli sciamani di ⟦Thunder Bluff=Picco del Tuono⟧, ti inonda di calore. Questo potere primordiale ti è estraneo, ma il sapiente potrebbe saperne di più...", "Sembri quasi risplendere, {race}. Che cos'hai lì?", "Se non mi inganno, questo fuoco è stato preso dalle scogliere di ⟦Thunder Bluff=Picco del Tuono⟧! Come canta del potere degli spiriti! Sei proprio <un/una> abile ladr<o/a>, {name}. Prendi questo come giusto compenso per la tua bravura. Ora, se solo avessimo le fiamme di tutte e tre le città...", 0xd6d267fd, 0x4526bcd9, 0x4d8c9c93, 0x35bceb01, 0x94adecd4, "....." },
  [9326] = { "Rubare la Fiamma di Sepulcra", "Riporta la ⟦Flame of the Undercity=Fiamma di Sepulcra⟧ al sapiente della festa.", "Questa fiamma, rubata alle rovine sopra ⟦Undercity=Sepulcra⟧, ti inonda di calore. Questo potere primordiale ti è estraneo, ma il sapiente potrebbe saperne di più...", "Sembri quasi risplendere, {race}. Che cos'hai lì?", "Mm... che fuoco strano! È smorzato, quasi cova sotto la cenere, ma il calore è intenso. E dici di averlo preso a ⟦Undercity=Sepulcra⟧? Affascinante. Con le fiamme di tutte e tre le città, chissà che cosa potremmo ottenere?", 0x65e82239, 0x889a7f0a, 0xdcc8620d, 0x35bceb01, 0x7a708213, "....." },
  [9330] = { "Rubare la Fiamma di Roccavento", "Riporta la ⟦Flame of Stormwind=Fiamma di Roccavento⟧ al cantastorie della festa.", "Questa fiamma, rubata dal cuore stesso di ⟦Stormwind=Roccavento⟧, ti inonda di calore. Questo potere primordiale ti è estraneo, ma il cantastorie potrebbe saperne di più...", "Sembri quasi risplendere, {race}. Che cos'hai lì?", "E questo fuoco così vivace... dici che viene da ⟦Stormwind=Roccavento⟧? Notevole! Dev'essere stata una bella avventura! Ti pagherò, naturalmente. Se trovi qualcos'altro del genere, torna a parlarmi.", 0xba6f08b3, 0xf51d4d42, 0xca4b7ab5, 0x35bceb01, 0xfaa39f41, "....." },
  [9331] = { "Rubare la Fiamma di Forgiardente", "Riporta la ⟦Flame of Ironforge=Fiamma di Forgiardente⟧ al cantastorie della festa.", "Questa fiamma, rubata dal cuore stesso di ⟦Ironforge=Forgiardente⟧, ti inonda di calore. Questo potere primordiale ti è estraneo, ma il cantastorie potrebbe saperne di più...", "Sembri quasi risplendere, {race}. Che cos'hai lì?", "Questa fiamma vigorosa dev'essere delle sale di ⟦Ironforge=Forgiardente⟧: è salda quanto i nani stessi. Un bel colpo, {name}. Se avessi i fuochi delle altre città... ah, ma lascia perdere. Ecco il tuo compenso.", 0x73da389b, 0x666a0263, 0x2834c54e, 0x35bceb01, 0xc94925a5, "....." },
  [9332] = { "Rubare la Fiamma di Darnassus", "Riporta la ⟦Flame of Darnassus=Fiamma di Darnassus⟧ al cantastorie della festa.", "Questa fiamma, rubata alle sponde di Teldrassil, ti inonda di calore. Questo potere primordiale ti è estraneo, ma il cantastorie potrebbe saperne di più...", "Sembri quasi risplendere, {race}. Che cos'hai lì?", "Questo fuoco è carico di un antico dolore, {name}. Dici di averlo strappato alle radici di Teldrassil? Affascinante! Ecco una ricompensa per la tua bravura. Torna da me se trovi qualcos'altro del genere: potrebbe tornarmi utile.", 0xadc93958, 0xbcda68cb, 0x50a8cf42, 0x35bceb01, 0xbdfd99a7, "....." },
  [9339] = { "La ricompensa del ladro", "Riporta la ⟦Flame of Stormwind=Fiamma di Roccavento⟧ a (NAME).", "Questa fiamma, rubata dal cuore stesso di ⟦Stormwind=Roccavento⟧, ti inonda di calore. Questo potere primordiale ti è estraneo, ma (NAME) potrebbe saperne di più...", nil, "Oggi hai dato prova di te, {name}.\n\nAnche se ho poco altro da darti, ho questa corona: un dono adatto a chi conquista. Che possa illuminare il tuo cammino.", 0x6fd2503e, 0x9e249500, 0xc3ca99b1, nil, 0xe7fe3c18, "...m." },
  [9353] = { "Riscatta il ⟦iCoke Gift Box Voucher=Buono per un Pacco Regalo iCola⟧", nil, nil, nil, nil, 0xcf2bfa37, nil, nil, nil, nil, ".mmmm" },
  [9362] = { "Il signore della guerra Krellian", "Recupera la ⟦Prismatic Shell=Conchiglia Prismatica⟧ per l'arcimago Xylem. L'arcimago risiede in una torre in cima alle scogliere di Azshara.", "Non c'è molto tempo, {name}! I miei incantesimi di divinazione hanno rivelato una potente fonte di magia. Non posso lasciare la torre, perciò ti chiedo di uccidere la vile creatura che possiede questo manufatto.\n\nQuel patetico cretino si chiama signore della guerra Krellian e si nasconde dietro le sue guardie nel ⟦Temple of Zin-Malor=Tempio di Zin-Malor⟧. Riducilo in cenere e prendi la conchiglia prismatica a cui tiene tanto.", "Non c'è tempo da perdere! Hai la conchiglia?", "Devo dire che questa conchiglia ha un'aura strana. Mi sembra giusto che parte della tua ricompensa per averla recuperata sia mettere alla prova le sue capacità magiche...", 0x724d1d5a, 0xe0e3c89c, 0x516377b1, 0xc66db138, 0x0c159361, "....." },
  [9364] = { "Magia frammentata", "Lancia Metamorfosi sugli Spitelash di Azshara e uccidi i cloni che compaiono qualche secondo dopo. Quando avrai ucciso 50 Polymorph Clone, torna dall'arcimago Xylem ad Azshara.", "Le mie ricerche hanno rivelato uno scopo particolare per la conchiglia prismatica.\n\nPorta con te la conchiglia e lancia il tuo incantesimo di metamorfosi sugli Spitelash di Azshara. Se aspetti qualche istante, l'aura caotica della conchiglia li farà dividere per qualche momento in diversi cloni più piccoli. Uccidi questi cloni il più in fretta possibile e la conchiglia raccoglierà la loro essenza.\n\nQuando la conchiglia sarà piena, riportamela.", "Hai raccolto la magia?", "Splendido! Splendido!\n\nOra possiamo trasformare questa magia in un nuovo incantesimo. Guarda!", 0xd47cc0a5, 0x8be4d194, 0xbd600d96, 0xbb84400e, 0x4ee27b4c, "....." },
  [9365] = { "La ricompensa del ladro", nil, nil, nil, "Oggi hai dato prova di te, {name}.\n\nAnche se ho poco altro da darti, ho questa corona: un dono adatto a chi conquista. Che possa illuminare il tuo cammino.", 0x6fd2503e, nil, nil, nil, 0xe7fe3c18, ".mmm." },
  [9367] = { "I Fuochi di Mezza Estate", "Tocca i falò di ⟦Stormwind=Roccavento⟧, ⟦Ironforge=Forgiardente⟧ e Darnassus, poi parla con un sapiente della festa nelle capitali.", "La Mezza Estate è di nuovo tra noi!\n\nOgni anno, come vuole la tradizione, vengono scelti dei custodi della fiamma per curare i falò delle nostre capitali. Mentre i fuochi ardono in tutta Azeroth, è fondamentale che i nostri siano i più caldi e luminosi, per rendere il giusto omaggio alla stagione.\n\nAnzi, ho un compito per te, se non ti dispiace. Non ho ancora saputo se i fuochi di tutte le capitali ardono come si deve. Vacci di persona e scaldati accanto ai fuochi: assicurati che siano belli caldi!", "I fuochi ardono?", "Eccellente! Pare che quest'anno abbiamo nominato custodi della fiamma scrupolosi, se i falò sono ben tenuti come dici. Grazie per averli ispezionati per me; ecco, prendi questo come piccolo segno della mia stima.", 0x5796d45d, 0x043f46cc, 0x3508e9e2, 0xf5f9a813, 0x7dc83d5c, "....." },
  [9368] = { "I Fuochi di Mezza Estate", "Tocca i falò di Orgrimmar, ⟦Thunder Bluff=Picco del Tuono⟧ e ⟦Undercity=Sepulcra⟧, poi parla con un cantastorie della festa nelle capitali.", "La Mezza Estate è di nuovo tra noi!\n\nOgni anno, come vuole la tradizione, vengono scelti dei custodi della fiamma per curare i falò delle nostre capitali. Mentre i fuochi ardono in tutta Azeroth, è fondamentale che i nostri siano i più caldi e luminosi, per rendere il giusto omaggio alla stagione.\n\nAnzi, ho un compito per te, se non ti dispiace. Non ho ancora saputo se i fuochi di tutte le capitali ardono come si deve. Vacci di persona e scaldati accanto ai fuochi: assicurati che siano belli caldi!", "Hai avuto fortuna, {name}?", "Eccellente! Pare che quest'anno abbiamo nominato custodi della fiamma scrupolosi, se i falò sono ben tenuti come dici. Grazie per averli ispezionati per me; ecco, prendi questo come piccolo segno della mia stima.", 0x5796d45d, 0xcedbcab1, 0x3508e9e2, 0x10763147, 0x7dc83d5c, "....." },
  [9378] = { "DND FLAG La temibile cittadella - Naxxramas", "L'arcimaga Angela Dosantos alla ⟦Light's Hope Chapel=Cappella della Luce⟧, nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧, ti concederà la ⟦Arcane Cloaking=Copertura Arcana⟧ senza alcun costo. Devi essere Osannato presso l'⟦Argent Dawn=Alba d'Argento⟧.", "Nel cuore di ⟦Plaguewood=Malaselva⟧ si trova l'ingresso della temibile cittadella di Naxxramas. Finora ogni tentativo di entrare era stato sventato dagli incantesimi di protezione posti sul portale runico. Fino a ora, almeno.\n\nAbbiamo escogitato un modo per entrare grazie a una sorta di copertura arcana permanente: un vecchio incantesimo minore del Kirin Tor, con qualche modifica di mia invenzione. Detto questo, la copertura è costosa; tuttavia, la tua dedizione alla causa dell'Alba è incrollabile! Rinunceremo a qualsiasi pagamento.", nil, nil, 0x5049ff9c, 0x69b682cf, 0x92dc890b, nil, nil, "...mm" },
  [9388] = { "Fiamme tremolanti a Kalimdor", "Visita i falò di ⟦Ashenvale=Valtetra⟧, delle ⟦Barrens=Savane⟧, di ⟦Darkshore=Rivafosca⟧ e delle ⟦Stonetalon Mountains=Vette di Petrartiglio⟧, poi parla con il custode della fiamma della festa.", "Oggi bruciano molte fiamme in tutto il mondo, {name}. I fuochi più difficili da curare sono quelli che ardono di verde: senza sorveglianza non restano accesi a lungo. Assicurati che i fuochi smeraldini ardano ancora su Kalimdor per il nostro custode della fiamma, eh?\n\nLi troverai vicino a ⟦Ratchet=Porto Paranco⟧ nelle ⟦Barrens=Savane⟧, vicino al ⟦Master's Glaive=Gladio del Maestro⟧ a ⟦Darkshore=Rivafosca⟧, nella foresta di ⟦Ashenvale=Valtetra⟧ presso il ponte vicino all'⟦Silverwing Outpost=Avamposto degli Alargentea⟧, e vicino alla strada per la ⟦Windshear Crag=Landa di Tagliavento⟧, lungo la strada principale delle ⟦Stonetalon Mountains=Vette di Petrartiglio⟧.", "I fuochi non possono spegnersi finché la festa non è finita!", "Ahhh, quindi ardono ancora. Ne sono lieto: non sarebbe giusto che quei fuochi si spegnessero prima del tempo. Hai fatto bene, {name}. Prendi questo, con la mia benedizione.", 0x4231b5a1, 0xebc13200, 0x9fb3b754, 0x7346e6f0, 0x87796b40, "....." },
  [9389] = { "Fiamme tremolanti nei Regni Orientali", "Visita i falò delle ⟦Hillsbrad Foothills=Alture di Colletorto⟧, della ⟦Silverpine Forest=Selva Pinargento⟧, delle ⟦Westfall=Marche Occidentali⟧ e delle ⟦Wetlands=Paludi Grigie⟧, poi parla con il custode della fiamma della festa.", "Per tradizione, i Fuochi di Mezza Estate illuminano il mondo con una miriade di fiamme. C'è chi sostiene che i fuochi verdi siano i più belli, perché sono i più difficili da mantenere e hanno una tinta così particolare.\n\nAssicurati che ardano ancora nei Regni Orientali per il nostro custode della fiamma. Si trovano vicino a Dun Modr nelle ⟦Wetlands=Paludi Grigie⟧, vicino a ⟦Pyrewood Village=Rovonero⟧ nella ⟦Silverpine Forest=Selva Pinargento⟧, sulle scogliere che sovrastano il faro nelle ⟦Westfall=Marche Occidentali⟧, e presso la torre in rovina nelle ⟦Hillsbrad Foothills=Alture di Colletorto⟧.", "Hai pensato al tuo compito?", "Allora sei tornat<o/a>, e ti sei occupat<o/a> delle fiamme smeraldine del continente. Che ne pensi, mm? Uno spettacolo raro e meraviglioso, senza dubbio. So però che le ricompense tangibili sono più apprezzate... quindi, ti prego, prendi questo per il disturbo.", 0x97c31d69, 0x8c77ebbe, 0x389c2696, 0x6640bff5, 0xe62c73ec, "....." },
  [9415] = { "Rapporto al maresciallo Bluewall", "Parla con il maresciallo Bluewall all'accampamento dell'⟦Alliance=Alleanza⟧ presso l'⟦Hive'Zora=Alveare Zora⟧.", "Siete le nuove reclute del maresciallo Bluewall? Certo che lo siete.\n\nChe cosa aspettate? Dei bravi soldati stanno morendo nel deserto. Non siete impazienti di unirvi a loro?\n\nForza, muovetevi, e non rinsecchitevi per strada.", nil, "L'⟦Alliance=Alleanza⟧ ha bisogno di tutte le braccia valide che riesce a trovare. L'⟦Horde=Orda⟧ riceve un flusso costante di rinforzi dalla parte settentrionale del continente, ed è stata dura tenere il passo.\n\nLascia che ti spieghi la situazione.", 0x4008d111, 0x31d6c9a1, 0x8a5e1ea6, nil, 0x10702533, "...m." },
  [9416] = { "Rapporto alla generale Kirika", "Parla con la generale Kirika all'accampamento dell'⟦Horde=Orda⟧ presso l'⟦Hive'Regal=Alveare Regal⟧.", "Devi essere una delle nuove reclute della generale Kirika. Era ora che ti facessi vedere. Nel deserto i corpi si logorano in fretta.\n\nI nani ricevono rinforzi ogni giorno, e non possiamo permetterci di perdere terreno nella nostra lotta per le risorse di ⟦Silithus=Silitus⟧.\n\nFatti dare le istruzioni dalla generale. Il mio compito non è addestrarti, solo trovarti.", nil, "Bene che tu sia qui, ma non c'è tempo da perdere in chiacchiere. Ti servono istruzioni, e poi devi andare là fuori.\n\nAscolta bene.", 0x99409d9a, 0x28dcdb78, 0xe9369a9b, nil, 0x55705a01, "...m." },
  [9419] = { "Setacciare il deserto", "Trova del silithyst e consegnalo al Silithyst Extractor, poi parla con il maresciallo Bluewall all'accampamento dell'⟦Alliance=Alleanza⟧ presso l'⟦Hive'Zora=Alveare Zora⟧.", "Di recente abbiamo scoperto che l'⟦Horde=Orda⟧ sta setacciando il deserto di ⟦Silithus=Silitus⟧ in cerca di risorse, ma non ce ne siamo curati molto. Pensavamo che non valesse la pena di stanziare molte truppe in questo deserto soffocante.\n\nPoi però si è scoperta l'importanza di queste risorse, e ora ci affanniamo per recuperare terreno.\n\nSe posso contare sul tuo aiuto, devi addentrarti nel deserto, recuperare il silithyst e riportarlo qui.", "Fa' attenzione là fuori, ma sbrigati. Non abbiamo tempo da perdere.", "Sia lodata la Luce, ce l'hai fatta.\n\nSe solo avessimo cominciato prima, il nostro bisogno non sarebbe così disperato. Non dobbiamo permettere che le ricchezze del deserto cadano nelle mani dell'⟦Horde=Orda⟧.", 0xc1479db1, 0x04326ec8, 0xe009e48c, 0xf4c8a037, 0x7b5cf1a9, "....." },
  [9422] = { "Setacciare il deserto", "Trova del silithyst e consegnalo al Silithyst Extractor, poi parla con la generale Kirika all'accampamento dell'⟦Horde=Orda⟧ presso l'⟦Hive'Regal=Alveare Regal⟧.", "Da tempo sfruttiamo le risorse cristalline del deserto di ⟦Silithus=Silitus⟧. Gli unici pericoli che affrontavamo venivano dalle creature che vivono qui e dalla sabbia, dalla polvere e dal caldo opprimenti.\n\nMa ora l'⟦Alliance=Alleanza⟧ sembra aver capito che cosa abbiamo trovato qui. Adesso è una corsa tra noi e loro per accaparrarsi le risorse naturali e tenerle lontane dall'altro.\n\nMi serve ogni paio di mani disponibile. Spero di avere anche le tue.", "Guardati dai pericoli del deserto, {name}. Con l'⟦Alliance=Alleanza⟧ in agguato tra le dune, ogni passo potrebbe essere l'ultimo.", "Hai fatto un buon lavoro, {name}. Queste risorse si aggiungeranno alle nostre scorte, e ogni briciola è un guadagno per noi e una perdita per il nemico.", 0xc1479db1, 0xd0a8a42f, 0xa727e0fd, 0x62964905, 0x42cdb6c9, "....." },
  [9556] = { "Al vincitore...", "Raccogli una bottiglia di ⟦Stratholme Holy Water=Acqua Santa di Stratholme⟧ nella città di Stratholme e consegnala al Mago di Lordaeron nel ⟦Mage Quarter=Quartiere dei Maghi⟧ di ⟦Stormwind=Roccavento⟧ o di ⟦Undercity=Sepulcra⟧, quando la tua fazione avrà vinto nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧.", "Hai senz'altro combattuto a lungo e duramente tra le torri, {race}. Vorremmo darti qualcosa in cambio della tua difesa di queste terre, ma prima devi dimostrarci di comprendere il peso delle tragedie che sono avvenute qui.\n\nPercorri le strade di Stratholme e trova una fiala di acqua santa. Quando l'avrai, raggiungi il Quartiere dei Maghi di ⟦Stormwind=Roccavento⟧ o di ⟦Undercity=Sepulcra⟧... Lì, se la vittoria in queste terre sarà vostra, troverai il mio collega.", nil, nil, 0xe7d4c82f, 0x5e95b376, 0xeb8092b9, nil, nil, "...mm" },
  [9664] = { "Nuovi avamposti", "Conquista la ⟦Crown Guard Tower=Torre della Corona⟧, la ⟦Eastwall Tower=Torre di Levante⟧, la ⟦Northpass Tower=Torre Passo Nord⟧ e la Torre di ⟦Plaguewood=Malaselva⟧ nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧, poi torna dall'emissario Whitebeard alla ⟦Light's Hope Chapel=Cappella della Luce⟧.", "Benvenut<o/a> nelle ⟦Plaguelands=Terre Infette⟧, {name}. Come sai, i Reietti e i loro alleati tengono le terre a ovest di qui nonostante tutti i nostri sforzi. I comandanti dell'⟦Alliance=Alleanza⟧ hanno deciso che qui a est costruiremo nuove fortificazioni per stringere il cappio attorno ai nostri nemici.\n\nA questo scopo conquisteremo e ricostruiremo torri abbandonate fin dai tempi di Lordaeron. Queste terre sono pericolose, e il tuo aiuto ci farebbe comodo.", "Quando le torri saranno sotto il nostro controllo, presto potremo accerchiare i Reietti. Dopodiché sarà solo questione di tempo prima di poterli schiacciare.", "Molto bene, {name}. Sarà importante per noi difendere queste torri dagli attacchi futuri, e per questo potremmo aver bisogno del tuo aiuto finché non arriveranno i rinforzi a mettere in sicurezza la zona.", 0x1b16d570, 0xd178e91f, 0x56bc8363, 0x18ee7a4a, 0x7ec604e7, "....." },
  [9665] = { "Rafforzare le nostre difese", "Conquista la ⟦Crown Guard Tower=Torre della Corona⟧, la ⟦Eastwall Tower=Torre di Levante⟧, la ⟦Northpass Tower=Torre Passo Nord⟧ e la Torre di ⟦Plaguewood=Malaselva⟧ nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧, poi torna dall'emissario Gormok alla ⟦Light's Hope Chapel=Cappella della Luce⟧.", "Agenti dei Reietti hanno scoperto un piano dell'⟦Alliance=Alleanza⟧ per stabilire nuove basi qui nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧, nelle torri abbandonate della zona.\n\nÈ fondamentale non permettere loro di stabilire una presenza significativa sui nostri confini orientali, e quindi dobbiamo respingere questa incursione dell'⟦Alliance=Alleanza⟧. Il nostro piano attuale è cacciarli da ogni torre che possano aver già conquistato e difendere da altri attacchi quelle sotto il nostro controllo.", "Devono essere degli sciocchi per pensare che li lasceremmo stabilire basi così vicino a una delle nostre capitali.\n\nDissangueremo le loro file finché non volteranno la coda per ritirarsi a sud.", "È una buona notizia, {name}. Qui nelle ⟦Plaguelands=Terre Infette⟧ la lotta sarà continua finché non avremo respinto del tutto le forze dell'⟦Alliance=Alleanza⟧.\n\nFino a quel giorno, spero che continuerai ad aiutarci.", 0x905ff178, 0x088acc5d, 0x65df63cb, 0x4ad0577c, 0x7fd2f5aa, "....." },
})
